const p=t=>`<p>${t}</p>`;
const table=(title,heads,rows)=>`<figure class="fp-figure"><figcaption>${title}</figcaption><div class="fp-table-wrap"><table><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></figure>`;
const flow=(title,rows)=>`<figure class="fp-figure"><figcaption>${title}</figcaption><div class="fp-flow">${rows.map(([a,b])=>`<div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div></figure>`;
const s=(title,html)=>({title,html});
const q=(title,data,ask,answer)=>({title,data,ask,answer:p(answer)});
const asbj=['ASBJ：会計基準検索システム','https://www.asb-j.jp/jp/accounting_standards_system/list.html'];
const ifrs=(slug,name)=>['IFRS Foundation：'+name,'https://www.ifrs.org/issued-standards/list-of-standards/'+slug+'/'];
export const accountingLectures=[
{number:1,lead:'同じ会社の取引を、利益・財産・現金の三つの角度で記録する。黒字なのに資金が減る理由まで追います。',goal:'架空の会社の一年間を使い、期末BS・PL・CFを自分でつなげられる。',sections:[
s('三つの表は別の会社の話ではない',p('PL（損益計算書）は一定期間の収益・費用・利益、BS（貸借対照表）は特定日時点の資産・負債・純資産、CF（キャッシュ・フロー計算書）は一定期間の現金の増減です。売上を立てた日と入金日は違うことがあるため、利益と現金は一致しません。まず「期間」と「時点」を区別して読みます。')+table('同じ取引をどこから見るか',['表','問い','例'],[['PL','一年にいくら稼いだか','商品を売り、原価と経費を差し引く'],['BS','決算日の財産と資金の出し手は誰か','未回収の売掛金、借入金、株主のお金'],['CF','現金は何で増減したか','回収、支払、設備購入、借入返済']])+p('以下はすべて架空の青葉製作所の簡略例です。単位は万円、消費税・配当・OCI・新規借入はありません。実在企業の決算値ではありません。三表を別々に暗記する代わりに、一つの取引が二つ以上の表へどう表れるかを考えます。')),
s('まずPLを最後まで読む',table('青葉製作所の年間PL（万円）',['項目','金額','意味'],[['売上高','1,000','当期に提供した商品'],['売上原価','600','売れた商品の原価'],['売上総利益','400','1,000−600'],['販管費','200','現金経費180＋減価償却20'],['営業利益','200','400−200'],['支払利息','10','金融費用'],['税引前利益','190','他の収益・費用なし'],['法人税等','57','例の税率30％'],['純利益','133','190−57']])+p('売上1,000のうち900だけ入金し、売掛金が100増えたとします。PLの売上を900へ直すのではありません。商品を提供した収益1,000と、現金回収900を分けます。利益133をそのまま銀行口座の増加とみなすと、資金計画を誤ります。')),
s('利益133から営業CF53へ',table('間接法の営業CF（利息・税は営業区分と仮定、万円）',['調整','金額','理由'],[['純利益','133','出発点'],['減価償却を加算','＋20','費用だが当期の現金支出ではない'],['売掛金の増加','−100','売上のうち未回収'],['在庫の増加','−30','原価未計上の仕入資金'],['買掛金の増加','＋30','仕入のうち未払い'],['営業CF','53','133＋20−100−30＋30']])+p('この例では利息10と税57は当期支払い済みです。直接法でも、回収900−仕入支払600−現金経費180−利息10−税57＝53です。在庫増加と買掛金増加が同額なので、仕入支払額は売上原価600と一致しています。調整の符号は暗記だけでなく、入金済みか支払済みかで説明します。')),
s('CFの終点はBSの現金',flow('期首から期末へ（万円）',[['期首現金100','営業CF＋53'],['設備購入−80','投資CF−80'],['借入元本返済−20','財務CF−20'],['現金増減−47','期末現金53＝100−47']])+table('BSの照合（万円）',['項目','期首','期末'],[['現金','100','53'],['売掛金','100','200'],['在庫','100','130'],['固定資産・純額','200','260＝200＋80−20'],['資産合計','500','643'],['買掛金','100','130'],['借入金','200','180'],['純資産','200','333＝200＋133'],['負債＋純資産','500','643']])+p('PLの純利益133は、配当などがなければBSの利益剰余金を増やします。CFの増減−47は、期首現金100を期末現金53へつなぎます。利益剰余金は現金の置き場ではなく純資産の項目です。実際には非支配持分、配当、OCI、現金同等物の範囲なども照合します。'))],questions:[q('営業CF',p('純利益133、減価償却20、売掛金増加100、在庫増加30、買掛金増加30（万円）。他調整なし。営業CF＝純利益＋償却−売掛金増−在庫増＋買掛金増。'),'営業CFは？','133＋20−100−30＋30＝53万円。'),q('期末現金',p('期首現金100、営業CF＋53、投資CF−80、財務CF−20（万円）。為替等の影響なし。期末＝期首＋三つのCF。'),'期末現金は？','100＋53−80−20＝53万円。純利益133とは違います。'),q('純資産',p('期首純資産200、当期純利益133（万円）。配当・増資・OCI・非支配持分等なし。期末純資産＝期首＋純利益。'),'期末純資産は？','333万円。利益が蓄積することと、その全額が現金で残ることは別です。')],sources:[asbj,ifrs('ias-7-statement-of-cash-flows','IAS 7')]},
{number:2,lead:'利益率を価格・販売量・原価・販管費へ分解し、増収でも減益になるケースを計算する。',goal:'粗利率と営業利益率を区別し、価格と費用の変化が利益へ与える影響を説明できる。',sections:[
s('売上が増えるだけでは足りない',p('売上高は、おおむね単価×販売数量です。売上原価は売れた商品やサービスに対応する費用、販管費は販売活動や会社運営の費用です。製造業の工場人件費と本社人件費のように、同じ給与でも機能により分類が変わります。何を売っている会社なのかを先に確認します。')+flow('利益を作る順番',[['単価×数量','売上高'],['売上−売上原価','売上総利益（粗利）'],['粗利−販管費','営業利益'],['営業利益÷売上','営業利益率']])+p('以下の金額は架空の店舗会社です。値引きで数量が増えても、一個当たりの粗利が下がれば利益が伸びるとは限りません。売上原価と仕入支払額も同じではありません。在庫や買掛金の変化は、利益率の分析とは別に確認します。')),
s('PLを一覧で比較する',table('架空の店舗会社・前年と当年（万円）',['項目','前年','当年'],[['売上高','1,000','1,200'],['売上原価','600','780'],['売上総利益','400','420'],['販管費','250','300'],['営業利益','150','120'],['粗利率','40％','35％'],['営業利益率','15％','10％']])+p('売上は20％増えたのに営業利益は20％減っています。粗利は20増えましたが、販管費が50増えたため差引30減益です。売上の増加だけを見て「好調」と決めるのではなく、どの段階の利益が増減したかを順にたどります。金額と率を両方並べると、規模の効果と採算の悪化を切り分けられます。')),
s('価格と数量を別々に動かす',table('架空の一商品モデル（原価以外の条件は同じ）',['項目','基準','値引き後'],[['単価','1,000円','900円'],['数量','1,000個','1,200個'],['一個当たり変動原価','600円','600円'],['売上','100万円','108万円'],['粗利','40万円','36万円']])+p('値引き後は数量20％増ですが、単価は10％下がります。粗利を40万円に保つには、40万円÷（900−600）＝約1,333.33個、整数なら1,334個以上必要です。販管費が固定なら粗利の差がそのまま営業利益の差へ移ります。実際には商品構成、仕入値、人員増加なども変化するため、条件を一つずつ追加します。')),
s('利益率の原因を注記へつなぐ',table('数字の次に確かめる資料',['変化','候補原因','確認先'],[['粗利率低下','値引き・原料高・低採算商品増','商品別売上、原価、会社説明'],['販管費率上昇','広告・採用・出店・一時費用','費用内訳、店舗数、投資方針'],['売上増と在庫増','需要増への準備か滞留か','在庫日数、評価損、翌期販売'],['利益増とCF低下','未回収売上や前払支出','営業CF、債権残高']])+p('原価率の上昇をすべて原材料高と断定してはいけません。販売構成や工場稼働率でも変わります。比較対象は同じ期間・連結範囲・会計基準にそろえ、単なる推測と会社が説明している事実を分けて書きます。利益率が高い会社でも、資産を多く使えば資本効率が高いとは限らず、第19回のROICへつながります。'))],questions:[q('営業利益率',p('売上1,200、原価780、販管費300（万円）。営業利益＝売上−原価−販管費、利益率＝営業利益÷売上。'),'営業利益と利益率は？','120万円、10％です。粗利420万円・35％とは区別します。'),q('値引き後の粗利',p('単価900円、数量1,200個、一個原価600円。粗利＝（単価−原価）×数量。'),'粗利は？','300×1,200＝36万円です。'),q('必要販売量',p('単価900円、一個変動原価600円、目標粗利40万円。必要量＝目標粗利÷一個粗利。整数切上げ。'),'何個必要？','400,000÷300＝1,333.33…なので1,334個です。')],sources:[asbj]},
{number:3,lead:'似ている利益指標を、何を引いた後の数字なのかで整理する。EBITDAと現金も区別します。',goal:'PLの営業利益からEBT・純利益へ進み、EBITDA・NOPATの調整を条件付きで計算できる。',sections:[
s('利益の名前より差し引いた費用を見る',p('営業利益は主な事業の損益、EBTは税引前利益、純利益は税金控除後の利益です。日本基準の経常利益は営業外損益も含みます。EBITは一般に利息・税引前の利益ですが、営業外項目の扱いによって営業利益と一致しません。IFRSには日本基準と同じ経常利益の区分をそのまま当てはめません。')+table('架空の簡略PL（万円、日本基準の例）',['項目','金額'],[['売上高','1,000'],['売上原価','600'],['販管費（償却40含む）','250'],['営業利益','150'],['受取利息','5'],['支払利息','20'],['経常利益','135'],['特別損失','15'],['税引前利益 EBT','120'],['税金（例30％）','36'],['純利益','84']])+p('営業利益150とEBT120の差30を、すべて支払利息と説明するのは誤りです。利息20だけでなく受取利息5と特別損失15が含まれます。各行を見て差の内訳を説明できることが大切です。')),
s('EBITDAは定義を添える',flow('この講義で使う簡略定義',[['営業利益150','償却40を足す'],['簡略EBITDA190','税・利息・運転資本・設備投資前の指標'],['会社の調整後EBITDA','のれん償却・一時費用等の定義を別確認']])+p('EBITDAには世界共通の単一定義があるわけではありません。この例では営業利益＋減価償却・償却と定義し190です。企業が示す調整後EBITDAは株式報酬や買収費用なども足し戻す場合があります。調整項目を毎年除外すると、本当に反復しているコストを見落とす可能性があります。')),
s('NOPATは事業だけを税引後にする',table('同じ利益を違う目的で使う（万円）',['指標','この例の計算','用途'],[['営業利益','150','事業の採算'],['簡略EBITDA','150＋40＝190','償却前の採算比較'],['EBT','150＋5−20−15＝120','税金前の全体損益'],['純利益','120−36＝84','株主側の会計損益'],['簡略NOPAT','150×（1−30％）＝105','事業の税引後採算・ROIC']])+p('NOPATはNet Operating Profit After Taxで、資金調達方法の差を取り除いて事業を比較するための分析指標です。実務では非事業損益・一時費用・税率の正常化を行います。純利益84をNOPAT105へ置き換えるのは、会社が税金を余分に払ったという意味ではありません。比較の目的が違うのです。')),
s('EBITDAがプラスでも資金不足は起こる',table('架空の資金感度（万円、EBITDA起点の概算）',['項目','金額'],[['簡略EBITDA','190'],['現金利息','−20'],['現金税','−36'],['運転資本増加','−80'],['設備投資','−100'],['概算残額','−46']])+p('この概算は正式な営業CFの計算ではなく、EBITDAから支払・投資・運転資本を落とす必要性を示すものです。非現金項目や営業外収益の回収などを省略しています。設備が老朽化している会社では、償却を全部足し戻すだけで稼ぐ力を評価すると更新投資を無視します。利益指標は資金繰りの代用品ではなく、CFとの橋渡しに使います。'))],questions:[q('EBT',p('営業利益150、受取利息5、支払利息20、特別損失15。他項目なし（万円）。EBT＝営業利益＋受取利息−支払利息−特別損失。'),'EBTは？','120万円。営業利益との差30を全部利息とはみなせません。'),q('EBITDA',p('営業利益150、営業費用内の償却40（万円）。本問のEBITDA＝営業利益＋償却。他調整なし。'),'EBITDAは？','190万円です。'),q('NOPAT',p('営業利益150、分析上の税率30％。NOPAT＝営業利益×（1−税率）、他調整なし。'),'NOPATは？','105万円。利息控除後の純利益ではありません。')],sources:[asbj,ifrs('ifrs-18-presentation-and-disclosure-in-financial-statements','IFRS 18')]},
{number:4,lead:'売掛金・在庫・買掛金・前受の増減から、売上の成長に必要な資金を見積もる。',goal:'営業運転資本の定義を明示し、増減とCFの符号を説明できる。',sections:[
s('運転資本には複数の定義がある',p('流動資産−流動負債という広い運転資本と、事業に必要な営業運転資本は別です。本講義は売掛金＋在庫−買掛金−契約負債と定義します。現金、有利子借入、税金、その他項目は除外します。企業比較では定義をそろえずに数字だけ並べないようにします。')+flow('営業の資金サイクル',[['仕入・生産','在庫に資金が滞留する'],['販売','売掛金になる'],['代金回収','現金が戻る'],['買掛金・前受','支払い猶予や顧客資金が必要資金を減らす']])+p('契約負債は、顧客から先に対価を受け取り、まだ商品やサービスを提供していない場合などの義務です。銀行借入とは性格が違います。前受が増えると資金面は助かりますが、将来の履行コストも伴うため、自由に使える利益と混同しません。')),
s('成長に必要な追加資金を計算',table('架空の事業の営業運転資本（万円）',['項目','期首','期末','変化'],[['売掛金','200','300','＋100'],['在庫','150','180','＋30'],['買掛金','100','130','＋30'],['契約負債','50','70','＋20'],['営業運転資本','200','280','＋80']])+p('資産側130増に対し、営業負債側50増が資金を支えています。差の80は追加で事業へ投入する資金です。純利益が100増えたとしても、それだけで100の現金が増えるとは限りません。営業CFの間接法では、この条件なら運転資本増加80を減算します。')),
s('符号を現金の動きで説明する',table('他の条件が同じ場合の営業CFへの方向',['変化','方向','理由'],[['売掛金増','減らす','売上の未回収分が増えた'],['在庫増','減らす','売れていない商品へ支出した'],['買掛金増','増やす','仕入支払を先へ延ばした'],['契約負債増','増やす','履行前に対価を受けた']])+p('ただしBS残高の単純差には、買収・為替・振替など現金取引以外が混ざることがあります。有報のCFとBS差が一致しなくても、すぐ誤りとはいえません。ここでの符号は、それらを除いた営業取引の増減です。現金支出を伴わず取得した在庫を、仕入支払の増加と決めつけないことも必要です。')),
s('低い運転資本は常によいのか',table('資金改善策と副作用',['策','資金効果','確認点'],[['回収を早める','売掛金減','値引きや顧客離反はないか'],['在庫を減らす','在庫減','欠品や販売機会損失はないか'],['支払を遅らせる','買掛金増','仕入先関係や資金難の兆候'],['前受を増やす','契約負債増','解約返金・将来原価の負担']])+p('小売や定額サービスでは、回収が先で支払いが後になり、営業運転資本がマイナスになることもあります。一方、受注生産や建設では長い回収期間が必要になる場合があります。業態と契約条件を確認したうえで、同業・自社過去・季節性と比較します。短期のCF改善が持続的な競争力なのか、支払いを押し延ばしただけなのかを分けて判断します。'))],questions:[q('期末運転資本',p('売掛金300、在庫180、買掛金130、契約負債70（万円）。定義＝売掛金＋在庫−買掛金−契約負債。'),'運転資本は？','280万円です。'),q('増加のCF効果',p('期首運転資本200、期末280。他の買収・為替・振替なし（万円）。営業CF調整＝−運転資本増加。'),'調整額は？','−80万円。事業に追加資金が必要です。'),q('前受の意味',p('顧客から一年分120万円を先に受け取った。まだサービス提供なし。契約負債として記録し、提供につれ収益へ振り替える条件。'),'受取時に120全部を利益としてよい？','いいえ。現金は増えますが、未履行の義務があり契約負債です。')],sources:[asbj,ifrs('ifrs-15-revenue-from-contracts-with-customers','IFRS 15')]},
{number:5,lead:'設備代を払う時期と費用を計上する時期の違い、減損が利益とCFへ与える影響を学ぶ。',goal:'固定資産の残高を投資・償却・売却・減損でつなぎ、基準差を区別できる。',sections:[
s('購入日に全額費用とは限らない',p('何年も使用する設備を取得した場合、資産として計上し、使用期間へ費用配分するのが減価償却です。購入代金の支払いは投資CF、償却費はPLの費用です。費用化と支払いのタイミングを分けることで、一年の利益と長期の設備投資を同時に理解できます。')+flow('架空の機械300万円・耐用年数5年・残存価額0',[['取得・支払','固定資産＋300、投資CF−300'],['毎年の定額償却','PL費用60、資産純額−60'],['一年後','帳簿価額240'],['営業CF間接法','非現金費用60を足し戻す']])+p('この例は取得直後から通年使用し、月割り・税務・消費税を省略します。会計上の耐用年数は経済的な使用見込み、税務上の償却は法令の条件によるため、必ず一致するとは限りません。土地は通常償却しない点も建物や機械と区別します。')),
s('期末固定資産をつなぐ',table('架空の固定資産純額の増減（万円）',['段階','金額'],[['期首純額','500'],['当期取得','＋200'],['減価償却','−80'],['売却資産の帳簿価額','−50'],['減損','−30'],['期末純額','540']])+p('売却代金70なら、売却益は70−帳簿価額50＝20、投資CFは＋70です。固定資産を70減らすのではありません。帳簿から消す金額と受け取った代金の差が損益になります。買収・為替・リース・建設仮勘定などを含む実際の注記では、増減表の項目を追加して照合します。')),
s('減損は将来回収の見直し',table('減損の基本的な基準差',['論点','日本基準の基本','IFRS・IAS 36の基本'],[['認識の判定','兆候がある場合、割引前将来CF等で認識判定','帳簿価額と回収可能価額を比較'],['測定','認識後に回収可能価額まで減額','回収可能価額まで減額'],['回収可能価額','正味売却価額と使用価値の高い方','処分コスト控除後公正価値と使用価値の高い方'],['戻入れ','固定資産減損の戻入れなし','一定条件で可。ただしのれんは不可']])+p('IFRSの簡略例で帳簿300、処分コスト控除後公正価値220、使用価値250なら回収可能価額250、減損50です。日本基準にこの判定をそのまま当てはめず、認識の段階を別に考えます。のれんや耐用年数を確定できない無形資産等では、毎年の検討が必要になる点にも注意します。')),
s('非現金費用でも悪化の情報はある',table('利益と資金を別々に評価する',['出来事','当期CF','経済的な意味'],[['機械購入','投資CFに支出','将来の生産能力への投資'],['償却','直接の当期支出なし','使用による費用配分'],['減損','直接の当期支出なし','過去の投資を回収しにくくなった'],['更新投資不足','短期CFが改善することも','将来の能力低下や多額更新の恐れ']])+p('減損を足し戻すから影響ゼロ、とはいえません。現金は当期に減らなくても、将来CF見積もりの悪化を示します。設備投資額と償却費の比率は参考になりますが、成長投資・維持投資・リース・物価上昇を切り分けなければ、償却費をそのまま必要更新投資額とみなすことはできません。'))],questions:[q('定額償却',p('取得価額300万円、残存価額0、耐用年数5年、通年使用。年償却＝（取得−残存）÷年数。'),'年償却と一年後純額は？','償却60万円、純額240万円です。'),q('売却',p('帳簿価額50、売却代金70（万円）。手数料・税なし。売却益＝代金−帳簿価額、入金は投資CF。'),'利益とCFは？','売却益20万円、投資CF＋70万円。'),q('IFRS減損',p('IAS 36の簡略例。帳簿300、処分コスト控除後公正価値220、使用価値250（万円）。回収可能価額は後二者の高い方、減損＝帳簿−回収可能価額。'),'減損額は？','回収可能価額250、減損50万円です。')],sources:[asbj,ifrs('ias-16-property-plant-and-equipment','IAS 16'),ifrs('ias-36-impairment-of-assets','IAS 36')]},
{number:6,lead:'買収代金を資産・負債・のれんへ分解し、買収後の利益に償却や減損が出る理由を学ぶ。',goal:'PPAの簡略計算とのれんの基準差を理解し、買収前後を同じ条件で比較できる。',sections:[
s('買収代金がすべてのれんではない',p('企業結合の取得法では、取得した識別可能な資産・負債を測定し、その純額と取得対価等の差からのれんを考えます。PPA（取得原価の配分）は、簿価になかった顧客関連資産や技術なども識別するプロセスです。会社の株式を買う個別会計と、取得会社の資産・負債を取り込む連結会計を分けます。')+flow('架空の100％取得・簡略例（万円）',[['取得対価1,000','識別可能資産900を評価'],['引受負債300','識別可能純資産600'],['1,000−600','のれん400'],['連結後','資産・負債と事業の収益費用を取り込む']])+p('この例では非支配持分、段階取得、条件付対価、取得関連費用、繰延税金を省略しています。実際ののれんを取得対価−簿価純資産だけで算出してはいけません。PPAで無形資産の評価が変わると、のれんや将来の償却費も変わります。')),
s('簿価と公正価値の差を配分する',table('識別可能純資産の架空の配分（万円）',['項目','簿価','取得時評価'],[['有形・その他資産','700','750'],['顧客関連無形資産','0','150'],['負債','300','300'],['純資産','400','600']])+p('純資産簿価400に対し、取得時の識別可能純資産は600です。顧客関係150の耐用年数を10年と仮定すると、通年償却15が買収後の費用になります。設備評価増50も、残り年数に応じた追加償却へつながる可能性があります。将来償却を除外した利益を使うなら、何を除外したかを明記して比較します。')),
s('日本基準とIFRSののれん',table('のれんの取得後の基本処理',['論点','日本基準','IFRS'],[['償却','原則20年以内で規則的償却','償却しない'],['減損','減損基準による検討','少なくとも年次の減損テスト等'],['減損後の戻入れ','なし','のれんはなし'],['注意','償却期間と金額を確認','CGUの配分・予測・割引率を確認']])+p('のれん400を日本基準で10年定額償却なら年40です。IFRSでは同じ40を毎年償却するわけではありません。この違いだけで、IFRSの買収が必ず経済的に優れているとはいえません。非償却でも回収見込みが悪化すれば減損が必要です。会計利益の差と、買収後の現金回収・統合効果の差は別に分析します。')),
s('買収の成功は売上増だけでは測れない',table('買収後に追うもの',['項目','確認する問い'],[['連結範囲','売上増は取得分か既存事業の成長か'],['費用','PPA償却・統合費用・資金調達利息は何か'],['貸借対照表','のれん・無形資産・借入がどれだけ増えたか'],['CF','買収対価と取得後の営業CFはどうか'],['投下資本利益率','のれんを含めた投下資本を回収できるか']])+p('買収した企業の売上を取り込めば連結売上は増えますが、既存店や既存製品が成長した証明ではありません。買収年度の取得日以降だけが連結PLに入るため、翌年との単純比較にも注意します。シナジーを織り込んだ計画は見込みであり、実績・追加投資・負債返済と区別して評価します。'))],questions:[q('のれん',p('100％取得。対価1,000、識別可能資産900、負債300（万円）。非支配持分等なし。のれん＝対価−（資産−負債）。'),'のれんは？','400万円です。'),q('無形資産償却',p('顧客関連資産150万円、残存0、10年定額、通年。年償却＝価額÷年数。'),'年償却は？','15万円です。'),q('基準差',p('のれん400万円。日本基準の例は10年定額償却、IFRSは非償却。この年の減損なし、他条件同じ。'),'毎年ののれん費用の差は？','日本基準40万円、IFRS0万円、差40万円。CFの差が40生じるという意味ではありません。')],sources:[asbj,ifrs('ifrs-3-business-combinations','IFRS 3'),ifrs('ias-36-impairment-of-assets','IAS 36')]},
{number:7,lead:'借りた設備の利用権と将来の支払義務をBSへ載せると、利益・CF・財務指標がどう変わるか。',goal:'使用権資産・リース負債の初年度を計算し、日本の新基準の適用時期を区別できる。',sections:[
s('借りていても資産と負債が立つ',p('IFRS 16の借手は、原則として使用権資産とリース負債を認識します。使用権資産は設備そのものの所有権ではなく、契約期間に使用する権利です。短期・少額等の例外や、そもそもリースかサービスかの判定を先に確認します。金額は契約書の支払総額をそのまま使うのでなく、割引現在価値などから測定します。')+flow('架空の設備利用契約',[['期首測定','使用権資産100、リース負債100'],['一年利用','使用権資産を20償却'],['利息発生','期首負債100×5％＝5'],['年末支払25','元本20＋利息5、負債残80']])+p('5年利用、残存0、定額償却、年末支払、初期直接費用・前払・インセンティブ等なしという簡略条件です。支払25が毎年同額で5年続く場合の現在価値が100だという設定ではありません。初年度計算用に初期測定100と支払25が与えられた例です。')),
s('日本基準は適用年度を確認',table('借手の基準と時期',['制度','基本的な位置付け'],[['IFRS 16','使用権資産・負債の認識が基本'],['従来の日本基準','ファイナンス・オペレーティング分類を確認'],['日本の新基準・第34号','2027年4月1日以後開始年度から適用'],['早期適用','2025年4月1日以後開始年度から可能'],['比較時の注意','2026年でも早期適用企業と未適用企業が混在し得る']])+p('2027年4月1日にすべての会社の決算値が一斉に切り替わる、という意味ではありません。年度の開始日と早期適用の有無を有報で確認します。契約の範囲や例外、移行措置があるため、日本の新基準とIFRSの詳細まで完全に同一とは説明しません。ここでは借手の基本構造を中心に扱います。')),
s('費用と支払を分けて読む',table('初年度の架空の変化（万円）',['項目','金額','記録'],[['使用権資産償却','20','PL費用・資産減'],['リース利息','5','PL金融費用'],['現金支払','25','元本20と利息5'],['期末使用権資産','80','100−20'],['期末リース負債','80','100＋5−25']])+p('支払額と償却＋利息は、この初年度例では偶然25で一致します。一般には返済表と償却表の形が違うため、毎年一致するとは限りません。CFでは元本返済と利息を分け、基準と会社の表示方針に従って分類します。現金支払総額が会計方針だけで消えるわけではありません。')),
s('EBITDAの上昇を実力向上と決めない',table('表示変更が比較へ及ぼす例',['指標','考えられる変化','読む際の補正'],[['EBITDA','従来の賃料費用が償却・利息へ移り上がることも','賃借支払や定義をそろえる'],['負債比率','リース負債認識で上がることも','有利子負債の範囲を統一'],['ROA','認識資産が増え下がることも','資産範囲と移行影響を確認'],['CF区分','営業から財務へ支払分類が移ることも','総支払・維持投資を合わせて見る']])+p('店舗型企業や航空会社などはリースの影響が大きくなり得ます。基準変更前後の営業CFやEBITDAをそのまま並べると、経済的には同じ契約なのに改善したように見えます。比較の目的が支払能力か企業価値かによって、リース負債を含める範囲と現金支払の扱いを明示します。'))],questions:[q('リース負債',p('期首負債100、利率5％、年末支払25（万円）。期末負債＝期首＋利息−支払。'),'期末は？','利息5、期末80万円です。'),q('使用権資産',p('初期資産100万円、残存0、5年定額、通年。初期直接費用等なし。'),'一年後の資産は？','償却20、残額80万円です。'),q('適用時期',p('日本新リース基準は2027年4月1日以後開始年度から、2025年4月1日以後開始年度は早期適用可。会社は4月開始、早期適用しない。'),'2026年4月開始年度から強制適用？','いいえ。条件上、2027年4月開始年度からです。')],sources:[['ASBJ：リースに関する会計基準','https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=157'],ifrs('ifrs-16-leases','IFRS 16')]},
{number:8,lead:'支払前の費用や会計と税務の時期差を、引当金・退職給付・繰延税金として整理する。',goal:'負債と費用、繰延税金資産と負債を区別し、回収可能性の制約を説明できる。',sections:[
s('将来の支払と当期の費用',p('引当金は、将来の特定の費用・損失を、その原因が当期以前に発生している等の要件に従って見積もるものです。日本基準の要件とIAS 37の現在義務・資源流出の可能性・信頼性ある見積り等は表現が違うため、問題の基準を確認します。何となく将来費用が出そうというだけで、自由に費用を前倒しすることはできません。')+table('架空の製品保証の簡略例（万円）',['時点','費用・負債・現金'],[['販売時','保証費用30、引当金30'],['翌期の保証支払20','現金−20、引当金−20'],['支払後残高','引当金10（再見積り前）'],['要件不成立の将来投資','単なる計画では引当金を作らない']])+p('費用が30でも、当期に30支払ったとは限りません。翌期の支払をもう一度全額費用にすると二重計上になります。ただし実績や見積りが変われば残高を調整します。偶発債務の注記と負債認識も別で、注記だけの項目をBSの既計上負債と混同しません。')),
s('退職給付は約束と積立を分ける',flow('確定給付制度の簡略構造',[['将来の給付見込み','割り引いて退職給付債務を考える'],['制度の積立資産','年金資産として区別する'],['債務−年金資産','純負債・資産の出発点'],['PL・OCI','勤務費用、利息、再測定などを基準別に確認']])+p('架空の債務500、年金資産420なら差80です。実際の計上額には基準ごとの取扱い、資産上限、個別と連結の違い等が関わるため、常に差がそのまま表示額とは限りません。確定拠出制度は拠出義務を中心に考え、会社が将来給付を約束する確定給付制度と区別します。割引率や寿命の仮定が負債へ影響する点を注記で確かめます。')),
s('繰延税金は税の時期差',table('一時差異の簡略例（税率30％、万円）',['条件','将来の税効果','区分'],[['引当費用100が当期損金不算入、将来支払時に損金','将来税を30減らす可能性','DTA・繰延税金資産'],['税務で償却が会計より100先行、将来逆転','将来税が30増える可能性','DTL・繰延税金負債'],['罰金等の永久差異','将来逆転しない','通常DTAを作らない']])+p('DTAは銀行預金でも、当期に国から30を受け取る権利でもありません。将来の課税所得等により税負担を軽くできる見込みが必要です。税率は差異が解消するときの適用税率等を使い、ここでは計算用30％とします。単なる当期会計利益と課税所得の差額へ機械的に掛ける方法では、永久差異を誤って資産化します。')),
s('回収可能性が利益を動かす',table('架空のDTA見直し（万円）',['段階','金額'],[['算定上の将来減算差異','100'],['税率','30％'],['計算上のDTA','30'],['回収できると認めたDTA','18'],['未認識・評価減相当','12']])+p('計算上30でも認識18なら、将来の税軽減30全部を資産として認めたわけではありません。既計上30から18へ見直す場合、通常は税金費用増などを通じ利益が悪化しますが、元の取引がOCI等なら表示場所も考慮します。税引前利益が変わらないのに純利益が大きく変わったときは、税率変更・DTA・過年度調整などを税金注記で確認します。'))],questions:[q('引当金の残高',p('期首保証引当金30、当期支払20（万円）。費用追加・見積変更なし。残高＝期首−支払。'),'残高は？','10万円です。支払20を同じ保証費用として再計上しません。'),q('DTA',p('将来減算一時差異100、税率30％（万円）。全額回収可能、他差異なし。DTA＝差異×税率。'),'DTAは？','30万円です。当期の現金還付とは限りません。'),q('回収見直し',p('既計上DTA30を18へ減額。他変更なし、全てPLの税金費用に反映。減額＝旧−新。'),'利益への影響は？','税金費用12増、純利益12減です。')],sources:[asbj,ifrs('ias-12-income-taxes','IAS 12'),ifrs('ias-19-employee-benefits','IAS 19'),ifrs('ias-37-provisions-contingent-liabilities-and-contingent-assets','IAS 37')]},
{number:9,lead:'営業・投資・財務の三つのCFを並べ、借入で現金を増やした会社と営業で増やした会社を区別する。',goal:'CFの分類と間接法を使い、現金増加の原因とFCFの定義を説明できる。',sections:[
s('現金が増えた理由を分ける',p('営業CFは主な収益獲得活動等、投資CFは長期資産や一定の投資の取得・処分、財務CFは資本・借入の調達返済等です。現金が増えたという終点だけでは、営業が強かったのか借入を増やしたのか分かりません。利息・配当などは基準と表示方針の違いがあるため、他社比較の前に区分を確認します。')+table('架空の二社のCF（万円、為替等なし）',['区分','A社','B社'],[['営業CF','200','−50'],['投資CF','−120','−100'],['財務CF','−50','180'],['現金増減','30','30']])+p('両社の現金は30増えていますが、B社は営業と投資の資金不足150を財務調達180で埋めています。それだけで倒産すると結論づけるのではなく、成長段階・手元流動性・借入期限・次期回収の見通しを確認します。A社の投資減少が成長機会の減少でないかも考えます。')),
s('間接法の調整を追う',table('架空の営業CFの簡略計算（万円）',['項目','調整'],[['純利益','120'],['償却','＋40'],['売却益（入金は投資CF）','−10'],['売掛金増','−30'],['在庫減','＋20'],['買掛金減','−15'],['営業CF','125']])+p('売却益10はPLに入っていますが、売却代金は投資CFに含めるので、営業CFの起点から利益10を除きます。減価償却40は費用になっていても当期の現金支払いではないため足し戻します。この例の税・利息の扱いは純利益に反映済み・支払済みで他の調整なしという条件です。実際の日本基準の間接法は税金等調整前当期純利益から始まることが多い点も確認します。')),
s('FCFは計算範囲を明記する',flow('本講義の簡略FCF',[['営業CF125','設備投資80を差し引く'],['簡略FCF45','125−80'],['注意','投資CF全体を設備投資とみなさない'],['企業価値計算','FCFFはNOPAT起点など別定義を確認']])+p('「営業CF＋投資CF」と呼ぶFCFもあれば「営業CF−設備投資」を使う場合もあります。投資CFには買収、有価証券売買、資産売却などが入るため、両式が常に一致するわけではありません。株主へ帰属するFCFEと全資金提供者向けのFCFFも別です。数式と資金の受け手を明記して使います。')),
s('三表の終点を照合する',table('架空の現金照合（万円）',['項目','金額'],[['期首現金同等物','100'],['営業CF','125'],['投資CF（設備−80、売却＋20）','−60'],['財務CF（借入返済）','−30'],['為替換算影響','5'],['期末現金同等物','140']])+p('BSの現金預金とCFの現金及び現金同等物の範囲が違うことがあります。長期の定期預金や使途制限などを調整する注記を見て照合します。この例ではその範囲差はないと仮定します。営業CFが一時的な支払い延期でよくなったのか、継続的な回収力で改善したのかも、運転資本と前後の期間を合わせて判断します。'))],questions:[q('間接法',p('純利益120、償却40、売却益10、売掛金増30、在庫減20、買掛金減15（万円）。他調整なし。営業CF＝120＋40−10−30＋20−15。'),'営業CFは？','125万円です。'),q('FCF',p('営業CF125、設備投資80（万円）。本問FCF＝営業CF−設備投資、買収等なし。'),'FCFは？','45万円です。'),q('現金照合',p('期首100、営業125、投資−60、財務−30、為替影響＋5（万円）。期末＝全部合計。'),'期末現金は？','140万円です。')],sources:[asbj,ifrs('ias-7-statement-of-cash-flows','IAS 7')]},
{number:10,lead:'決算短信・有報・監査・会計基準を整理し、どの数字をどの資料で確認するかを学ぶ。',goal:'連結範囲・期間・基準・監査対象を確認してから企業比較を始められる。',sections:[
s('同じ会社でも資料の目的が違う',p('決算短信は決算情報を素早く伝える資料、有価証券報告書は法定開示として事業・リスク・財務諸表・注記等を詳しく伝える資料です。説明資料は経営者が事業の背景を説明するために役立ちますが、強調された指標だけでは全体像が分かりません。提出日と対象期間を混同しないことも必要です。')+table('確認したい問いから資料を選ぶ',['問い','まず見る資料','次の確認'],[['最近の業績','決算短信','前年同期、通期予想、後発事象'],['負債の詳しい条件','有報の注記','期限、担保、財務制限条項'],['事業の変化','説明資料・有報事業情報','定義、連結範囲、セグメント'],['経営者の数値調整','説明資料の調整表','公式PLとの照合']])+p('取引所の適時開示とEDINETの法定開示も入口が違います。数字を記事へ転記するときは、資料名、対象年度、単位、連結か個別か、実績か予想かを添えます。最新という言葉だけで対象時点が分からない表示は避けます。')),
s('監査は投資の保証ではない',flow('資料の読み方',[['財務諸表','認識・測定・表示の基準を確認'],['監査報告書','意見、対象、強調事項等を読む'],['KAM','監査上特に重要だった事項を理解'],['投資判断','将来利益や株価の保証とは切り離す']])+p('監査は財務諸表全体に重要な虚偽表示がないか等について合理的保証を得るもので、すべての取引に誤りがないという絶対保証ではありません。無限定適正意見でも、将来の倒産が起きない、株価が上がるという保証にはなりません。KAMも、その項目が必ず不正という意味ではなく、監査上の注意領域を示すものです。')),
s('比較の四条件をそろえる',table('架空の数字を比較する前の点検',['項目','A資料','B資料','そのまま比較？'],[['範囲','連結売上1,000','個別売上600','不可・子会社の範囲が違う'],['期間','12か月利益100','6か月利益70','不可・季節性がある'],['基準','日本基準','IFRS','項目定義と調整を確認'],['性格','実績100','予想120','実績と計画を分ける']])+p('例えば六か月利益70を二倍して140とするだけでは、季節性・一時利益・取得時期を無視します。会計方針変更や訂正で過年度数値が組み替えられている場合、最新資料の比較数値を使うのが基本です。異なる期間のBS平均とPLを混ぜた回転率も誤りの原因になります。')),
s('基準の変更を注記へつなぐ',table('2026年の読者が注意する例',['変化','確認するもの'],[['日本の新リース基準','年度開始日・早期適用・影響額'],['IFRS 18','2027年1月1日以後開始年度から適用、早期適用可'],['IFRS表示の変更','利益区分・会社定義指標・過年度比較'],['基準の違い','のれん、OCI、金融商品等の方針']])+p('IFRS 18は表示・開示の新基準であり、2026年の全IFRS企業がすでに強制適用していると説明しません。適用時期の前後で表のラベルやCFの区分等が変わる場合は、数値だけでなく調整注記を読みます。本講座は独自教材なので、試験範囲と公式通信教育の内容は日本証券アナリスト協会の案内で別に確認します。'))],questions:[q('比較の範囲',p('Aは連結売上1,000、Bは同社の個別売上600（万円）。連結には子会社を含み、個別には含まない。'),'差400を成長と呼べる？','呼べません。範囲が違うためです。同じ範囲・同じ期間を比較します。'),q('監査',p('監査は重要な虚偽表示の有無について合理的保証を得る手続きで、将来株価・倒産回避の保証ではない。'),'適正意見なら株価上昇が保証される？','いいえ。会計情報の監査と投資成果は別です。'),q('期間',p('上半期利益70万円、通期は12か月。季節性と下半期費用は不明。'),'通期140と断定できる？','できません。二倍は仮定に過ぎず、通期予想や季節性を確認します。')],sources:[asbj,['金融庁：EDINET','https://disclosure2.edinet-fsa.go.jp/'],ifrs('ifrs-18-presentation-and-disclosure-in-financial-statements','IFRS 18')]}
];
accountingLectures.push(
{number:11,lead:'契約を結んだ日、請求した日、入金した日と、売上を認識する日は同じとは限らない。',goal:'履行義務と対価を分け、契約資産・売掛金・契約負債の違いを説明できる。',sections:[
s('売上は入金日だけでは決まらない',p('収益認識の基本は、約束した財やサービスを顧客へ移転したときに、その対価を収益として認識することです。契約を識別し、履行義務を識別し、取引価格を算定・配分し、義務を充足したときに認識します。単なる受注、請求、入金を一律の売上計上日とはしません。')+flow('収益認識の五つのステップ',[['契約','当事者の権利や支払条件等を確認'],['履行義務','別個の財・サービスを識別'],['取引価格','変動対価等を検討'],['配分','独立販売価格等で義務へ配分'],['充足','一定時点か一定期間かを判定']])+p('期間にわたり認識するには所定の要件が必要で、長期契約だから自動的に毎月均等の売上とは限りません。本人・代理人の判定も重要です。代理人が扱う取引の総額をすべて自社売上とすると、規模や利益率の比較を誤ります。')),
s('セット契約の対価を配分',table('架空の機器と保守のセット（万円）',['義務','独立販売価格','対価120の配分'],[['機器','100','120×100÷150＝80'],['一年保守','50','120×50÷150＝40'],['合計','150','120']])+p('機器は引渡時に支配が移転し、保守は一年均等にサービス提供する条件とします。機器引渡時に80を認識し、保守は月40÷12です。値引き30を機器だけに任意配分するのではなく、ここでは相対的独立販売価格の比率を使います。配分の例外や変動対価がある実契約では、追加の要件を確認します。')),
s('債権と契約資産・負債',table('権利・義務の状態を見分ける',['状態','項目','例'],[['請求権が時間経過以外の条件なし','売掛金等','引渡済み、支払期日待ち'],['対価の権利に他の履行等の条件あり','契約資産','途中工程を履行したが追加条件あり'],['先に対価を受け未履行','契約負債','年間保守代の前受'],['契約だけで未履行・未入金','通常直ちに売上ではない','翌期引渡の受注']])+p('契約資産は売掛金の難しい別名ではありません。請求するために残る条件が違います。前受で現金が増えても、未履行部分を当期利益とみなせません。決算分析では売上の増加と契約資産の増加を比べ、認識の判断・回収見通し・翌期振替を注記で確認します。')),
s('進捗度の見積りが利益を変える',table('架空の期間認識の例（要件成立、原価比例）',['条件','金額・計算'],[['総対価','1,000万円'],['見積総原価','800万円'],['当期までの適格原価','200万円'],['進捗度','200÷800＝25％'],['累計収益','1,000×25％＝250万円'],['累計粗利','250−200＝50万円']])+p('もし見積総原価が1,000へ増えると、同じ発生原価200でも進捗は20％、累計収益200となります。これは当期までの収益見積りも変える可能性を示します。異常な仕損等を原価へ機械的に足して進捗を上げるのでなく、履行の実態を表す測定かを確認します。将来の損失契約の検討も、収益の計算とは別に必要です。'))],questions:[q('配分',p('セット対価120、機器独立価格100、保守50（万円）。相対配分＝対価×義務の独立価格÷150。'),'機器の配分は？','80万円です。'),q('前受',p('一年保守40万円を前受。均等提供し3か月経過。収益＝40×3÷12、残額は契約負債。他条件なし。'),'収益と負債残は？','収益10万円、契約負債30万円です。'),q('進捗',p('契約対価1,000、見積総原価800、累計適格原価200（万円）。期間認識要件成立。進捗＝200÷800、収益＝対価×進捗。'),'累計収益は？','250万円です。')],sources:[asbj,ifrs('ifrs-15-revenue-from-contracts-with-customers','IFRS 15')]},
{number:12,lead:'保有目的や契約の性質で金融資産の測定が変わる。時価変動が利益かOCIかを整理する。',goal:'日本基準の区分とIFRS 9を混同せず、償却原価・公正価値・信用損失を区別できる。',sections:[
s('金融資産の種類と測定を分ける',p('金融商品は株式、債券、貸付、債権、デリバティブ等で、同じ値上がりでも保有区分によって表示が違います。時価は市場で売買できる価値、償却原価は実効金利法等で利息や回収を反映する測定です。時価変動を認識しない区分でも、信用リスクがないという意味ではありません。')+table('日本基準の有価証券の基本整理',['区分','基本的測定','損益・純資産'],[['売買目的','時価','評価差額は損益'],['満期保有目的債券','償却原価','要件と減損を別確認'],['子会社・関連会社株式（個別）','取得原価が基本','減損等を検討'],['その他有価証券','時価が基本、例外等あり','評価差額の純資産計上等']])+p('その他有価証券の評価方法や市場価格のない株式等の例外を確認します。子会社株式の個別BS表示と、連結で子会社資産負債を取り込む処理は違います。単に「株式はすべて時価で利益に入る」と覚えることはできません。')),
s('IFRS 9は事業モデルとCF特性',flow('負債性金融資産の基本判定',[['契約CF','元本・利息のみというSPPIを満たすか'],['回収目的＋SPPI','償却原価の候補'],['回収と売却＋SPPI','FVOCIの候補'],['その他','FVTPLが基本（指定等の条件あり）']])+p('この図は負債性金融資産の基本構造です。株式へSPPI判定をそのまま使いません。非売買目的の持分金融商品には、一定条件で取消不能のOCI表示選択があります。日本基準の「その他有価証券」とIFRSのFVOCIは名前が似ていても、売却時の振替などの扱いが違います。基準別に判断します。')),
s('実効金利で帳簿をつなぐ',table('架空の償却原価の一年（万円）',['項目','計算'],[['期首帳簿価額','950'],['実効金利','6％'],['利息収益','950×6％＝57'],['現金クーポン','40'],['期末償却原価（損失なし）','950＋57−40＝967']])+p('額面やクーポンだけで利息収益を決めるのではありません。購入時の割引等が実効金利に反映され、現金利息40と会計利息57が違う例です。ここでは次年度以降の償還条件を使わず、与えられた実効金利による初年度を計算します。時価が920へ下がったとしても、その差47をこの区分の通常評価損とする計算ではありません。')),
s('価格変動と信用損失は別',table('同じ価値低下でも原因を確認',['論点','確認するもの'],[['金利上昇による時価下落','市場金利、期間、区分'],['発行者の信用悪化','回収可能性、信用損失の測定'],['IFRSのECL','期待信用損失と信用リスク増加等'],['日本基準の減損等','適用される認識・測定の要件']])+p('IFRS 9の一定の資産等には予想信用損失を認識する枠組みがあります。実際に貸倒れたときだけ費用にする考えではありません。一方、公正価値の評価差額と信用損失を同じ数字として二重に引かないよう注意します。どの残高がどの基準で測定され、損失がどこに表示されるかを注記へつなぎます。'))],questions:[q('実効金利',p('期首償却原価950、実効金利6％、現金クーポン40（万円）。期末＝期首＋期首×金利−クーポン。減損等なし。'),'期末は？','967万円です。'),q('評価差額',p('日本基準の売買目的株式。取得100、決算時時価120（万円）。他取引・税なし。差額は損益。'),'評価益は？','20万円です。'),q('区分',p('IFRSの負債性資産は、回収目的の事業モデルとSPPIをともに満たすと償却原価の候補。特別な指定なし。'),'保有者が回収目的だけなら十分？','いいえ。契約CF特性の条件も確認します。')],sources:[asbj,ifrs('ifrs-9-financial-instruments','IFRS 9')]},
{number:13,lead:'先物・スワップ等の評価損益と、リスク管理の対象の損益の時期を合わせる考え方を学ぶ。',goal:'ヘッジの経済効果とヘッジ会計の適用要件を区別し、OCIと損益の動きを理解できる。',sections:[
s('リスクを減らす取引と会計は別',p('デリバティブは原資産・金利・為替等の変化に連動する契約です。金利スワップで借入の変動金利を固定化するように、経済的なリスク管理に使えます。しかし相殺する取引をしただけで、自動的にヘッジ会計が使えるわけではありません。対象、手段、リスク、関係を特定し、文書化と有効性等の要件を満たす必要があります。')+flow('外貨の予定仕入を守る例',[['予定仕入','ドル高で円支払が増えるリスク'],['為替予約','一定の為替でドル購入を約束'],['経済効果','対象と手段の変動を相殺する'],['会計上の課題','予約評価益と仕入費用の認識時期が違う']])+p('この講義は日本基準とIFRSの共通する狙いを示し、数値例はIFRSの簡略キャッシュ・フロー・ヘッジです。日本基準の繰延ヘッジや特例処理へ、そのまま同じ仕訳を使うと説明しません。投機取引の損失をヘッジと名付けて利益を隠せる制度でもありません。')),
s('公正価値とCFのヘッジ',table('二つの基本目的',['型','守るもの','基本的な表示の考え方'],[['公正価値ヘッジ','認識済資産負債等の公正価値変動','手段と対象の所定の変動を損益等へ反映'],['CFヘッジ','将来CFの変動','手段の有効部分をOCI等へ、非有効部分は損益'],['非指定のデリバティブ','ヘッジ会計の要件外','通常、公正価値変動を損益へ']])+p('固定金利の債券価格を守る話と、変動金利借入の支払額を守る話は違います。何が変わると困るのかを先に言葉にしてから型を選びます。対象が非金融資産の取得になるときのベーシス調整など、OCIの行き先は条件で変わるため、何でも翌期利益へ振替とはしません。')),
s('有効部分と非有効部分',table('架空のCFヘッジ評価（万円、適用要件成立）',['内容','金額','本例の表示'],[['ヘッジ手段の評価益','12','分けて認識'],['有効部分','10','OCI'],['非有効部分','2','PL'],['現金決済','まだなし','評価益12と入金は別']])+p('評価益12が立っても、全額が当期のPL利益になるとは限りません。また評価益がそのまま口座の入金ではありません。OCIへ置いた10は、対象の履行・損益認識・取消等に応じて所定の処理をします。ヘッジの規模や期間が対象とずれると非有効が発生し得ますが、非有効があることだけで経済的なリスク管理がすべて失敗したとはいえません。')),
s('注記でリスク管理を確認する',table('ヘッジ注記で見る事項',['項目','問い'],[['想定元本','契約の規模。現在の損失額そのものではない'],['公正価値','資産・負債の評価額'],['満期','対象の支払・回収時期と合うか'],['対象リスク','金利・為替・商品等のどれか'],['OCI残高と振替','過年度からの繰延分がどう動くか']])+p('想定元本100億円とデリバティブ負債2億円は別の概念です。想定元本を全部借入金として足すと負債を誤認します。一方、少ない初期支払で大きなリスクを負えるため、担保や追加証拠金、取引相手リスクも無視できません。損益だけでなく契約の目的と資金負担を合わせて読みます。'))],questions:[q('表示の分割',p('IFRSのCFヘッジ。手段評価益12、有効部分10、非有効部分2（万円）。要件成立、税なし。有効はOCI、非有効はPL。'),'OCIとPLの金額は？','OCI10万円、PL評価益2万円です。'),q('自動適用か',p('ヘッジ会計には対象・手段の特定、文書化、有効性等の適用要件がある。'),'相殺取引をしただけで適用できる？','できません。経済効果と会計要件は別です。'),q('想定元本',p('想定元本100億円、公正価値負債2億円。想定元本は契約計算の基礎で、評価損失額ではない。'),'現在の評価負債は100億円？','いいえ。この条件では2億円です。')],sources:[asbj,ifrs('ifrs-9-financial-instruments','IFRS 9')]},
{number:14,lead:'親子会社を一つの経済単位として示すとき、内部売上や内部利益が消える理由を学ぶ。',goal:'連結範囲・内部取引・未実現利益・非支配持分を簡略例で計算できる。',sections:[
s('連結は持株比率だけでなく支配を見る',p('連結財務諸表は、親会社と支配する子会社を一つの経済単位として表します。子会社の売上・資産・負債を基本的に全額取り込み、親の持分以外を非支配持分として区別します。80％保有なら売上の80％だけを取り込む方式ではありません。支配の判定は会計基準と具体的な権利関係を確認します。')+flow('架空の80％子会社',[['親会社＋子会社','各社の財務数値を合算'],['内部取引消去','グループ外との取引へそろえる'],['取得時差額等','のれん・PPA等を調整'],['非支配持分20％','純資産と利益の帰属を分ける']])+p('過半数でない持分でも支配が認められることがあり、過半数だけを唯一の判定基準にはしません。買収年度のPLは取得日以後の対象期間を取り込むため、BSの期末範囲と年間PLの期間が異なる場合があります。企業比較は連結範囲と取得時期をそろえて考えます。')),
s('内部売上は外部売上ではない',table('架空の売上合算（万円）',['内容','金額'],[['親の売上（子への100含む）','1,000'],['子の売上','500'],['単純合算','1,500'],['内部売上の消去','−100'],['連結売上','1,400']])+p('親が子へ売り、子が外部へ売ると、内部分を残したままでは同じ流れを二重に売上へ数えます。内部の債権・債務も双方から消します。消去したから代金がグループ外から回収されたわけではなく、最終顧客の売掛金は残ります。内部売上消去と資金回収を混同しないようにします。')),
s('期末在庫の内部利益を消す',table('架空の親→子の商品移転（万円）',['条件','金額'],[['親の原価','80'],['子への販売価格','100'],['内部利益','20'],['子の期末残存割合','50％'],['未実現利益','20×50％＝10'],['連結在庫調整','−10']])+p('外部へ売れていない半分に含まれるグループ内利益10を消します。この例は親から子へのダウンストリームで、税効果を省略します。子から親へのアップストリームでは非支配持分への影響も検討します。翌期に外部へ販売されると過年度の消去分を実現させるため、消去は永久に利益をなくす処理ではありません。')),
s('全体の利益と親株主の利益',table('架空の利益帰属（万円、他調整なし）',['項目','金額'],[['親の外部利益','100'],['子の利益','50'],['連結全体利益','150'],['非支配持分利益','50×20％＝10'],['親会社株主帰属利益','140']])+p('非支配持分は借入金ではなく、他の株主に帰属する持分です。PLの全体利益150と親株主帰属140のどちらをEPSや親株主ROEへ使うかを合わせます。実際にはPPA償却・未実現利益・持分変化等があるため、子会社の単体利益×比率で必ず完全一致するとは限りません。'))],questions:[q('連結売上',p('親売上1,000、子売上500、親の売上中内部100（万円）。連結売上＝合算−内部。他消去なし。'),'連結売上は？','1,400万円です。'),q('未実現利益',p('親原価80、子への販売100、子の期末残存50％（万円）。未実現利益＝（100−80）×残存率。税等なし。'),'消去額は？','10万円です。'),q('利益帰属',p('親外部利益100、子利益50、親保有80％。他調整なし。非支配利益＝50×20％、親帰属＝150−非支配。'),'親帰属利益は？','140万円です。')],sources:[asbj,ifrs('ifrs-10-consolidated-financial-statements','IFRS 10')]},
{number:15,lead:'支配していないが重要な影響力がある投資先は、売上全額でなく持分に対応する損益を反映する。',goal:'持分法の投資残高と配当を計算し、子会社連結や共同支配との違いを説明できる。',sections:[
s('影響力と支配を区別する',p('関連会社は、支配ではなく財務・営業方針へ重要な影響力を持つ投資先を基本に考えます。持分法では投資先の取得後損益等を持分に応じて投資簿価へ反映します。議決権20％は重要な影響力の推定等で使われますが、常に20％だけで機械的に決定するのではありません。権利や実態を確認します。')+table('投資先を取り込む基本の違い',['状態','表示の基本'],[['支配する子会社','連結して売上・資産負債等を取り込む'],['重要な影響力のある関連会社','持分法で投資・損益を反映'],['影響力等のない投資','適用される金融商品区分で処理'],['共同支配','契約上の全員一致等と権利義務を確認']])+p('持分法投資先の売上が1,000でも、自社連結売上へ300を機械的に加えるわけではありません。主に投資一行と持分法損益等で反映します。日本基準とIFRSでは共同支配取引の分類等に違いがあるため、共同事業ならすべて同じ処理と覚えないようにします。')),
s('投資残高をつなぐ',table('架空の30％保有の一年（万円）',['項目','金額'],[['期首投資簿価','300'],['投資先利益100の30％','＋30'],['投資先配当40の30％','−12'],['投資先OCI20の30％','＋6'],['期末投資簿価（他調整なし）','324']])+p('利益30を持分法損益として反映した後、配当12をまた利益として足すと二重計上になります。この簡略例では配当は投資簿価を減らし、現金を増やします。実際には取得時差額の償却、未実現利益、減損、会計方針調整などがあり、投資先純利益×持分率だけで一致しない場合があります。')),
s('配当と利益の時間差',flow('投資先利益が現金になるまで',[['投資先が利益100','投資会社は持分法利益30を認識'],['投資先で資金を留保','投資会社の現金はまだ増えない'],['配当40を決議・支払','投資会社は持分分12を受け取る'],['投資簿価','取得後利益の蓄積と配当で変わる']])+p('持分法利益が大きい会社では、利益と手元資金の関係を特に確認します。投資先が設備投資や返済に資金を使う場合、自社へ同額が配当されるとは限りません。利益の持分と現金配当を分けることは、配当余力や借入返済力を考える際に重要です。持分法投資先の負債が連結BSへ全額入らなくても、投資や保証のリスクは注記で見る必要があります。')),
s('共同支配を権利義務で見る',table('IFRSの共同支配の基本整理',['型','権利・義務','基本処理'],[['共同営業','資産への権利・負債への義務','権利義務に対応する資産負債等を認識'],['共同支配企業','純資産への権利','持分法'],['共同で投資しただけ','共同支配とは限らない','契約と意思決定を確認']])+p('共同支配は重要な活動の意思決定に共同支配当事者の全員一致が必要であるなど、契約上の支配共有を検討します。50対50の出資という数字だけで処理を決めません。分析では持分法投資の残高・利益寄与・配当・追加出資・保証を一覧で確認し、経営者が説明する連結利益への寄与と実際のキャッシュ回収を分けて把握します。'))],questions:[q('持分利益',p('投資先利益100万円、持分30％。取得差額等なし。持分法利益＝利益×持分。'),'利益はいくら？','30万円です。'),q('残高',p('期首投資300、持分利益30、受取配当12、持分OCI6（万円）。他調整なし。期末＝300＋30−12＋6。'),'期末投資は？','324万円です。'),q('配当',p('持分法で利益30万円をすでに認識。取得後利益から配当12万円受取。配当は投資簿価減額。'),'配当12も追加利益？','いいえ。この条件では現金増と投資簿価減です。')],sources:[asbj,ifrs('ias-28-investments-in-associates-and-joint-ventures','IAS 28'),ifrs('ifrs-11-joint-arrangements','IFRS 11')]},
{number:16,lead:'外貨建債権の為替損益と、海外子会社を円へ換算する調整を別々に整理する。',goal:'取引の換算差と在外事業の換算差を区別し、円表示の利益増を実態成長と決めつけない。',sections:[
s('取引の通貨と機能通貨',p('外国通貨で売上や借入を行う取引と、外国事業の財務諸表を表示通貨へ換算する処理は違います。IFRSでは機能通貨は企業の主たる経済環境の通貨で、好きな通貨へ自由に変えるものではありません。自社が円の機能通貨でドル債権を持つ場合と、ドル機能通貨の子会社を円連結へ換算する場合を分けます。')+table('二つの換算を混ぜない',['場面','見ているもの','差額の基本'],[['円機能通貨の会社のドル債権','外貨建貨幣性項目','通常は為替差損益'],['海外事業のドル財務諸表を円表示','在外事業の財務諸表','換算差をOCI等へ'],['非貨幣性項目','原価か公正価値か等','測定と基準により換算日を確認']])+p('すべての外貨残高を決算日のレートでPLへ評価するわけではありません。取得原価の非貨幣性資産や公正価値評価などは扱いが変わります。単位もドルと円を混ぜないよう、金額の横に通貨・レート・日付を並べます。')),
s('外貨売掛金の損益',table('架空の1万ドル売掛金（円機能通貨）',['時点','レート','円評価'],[['販売時','140円／ドル','140万円'],['決算日・未回収','150円／ドル','150万円'],['期末換算差','＋10円／ドル','為替益10万円'],['翌期回収時','148円／ドル','148万円入金、翌期差損2万円']])+p('売上は取引時の140万円を出発点にし、決算日の円安による差10万円を通常の為替損益として区別します。入金148万円が全部売上ではありません。売上と為替益の分類を分けないと、商品販売の成長と円安効果が混ざります。ヘッジ指定や特別な条件のない簡略例です。')),
s('海外子会社の換算差',flow('在外事業を円へ換算する基本',[['資産・負債','期末レートで換算するのが基本'],['収益・費用','取引日、合理的近似なら平均等を使う'],['純資産の構成','履歴や当期変動のレートを区別'],['差額','OCI・為替換算調整等に表れる']])+p('資産負債は期末、年間の利益は平均等で換算するため、単純にすべてへ同じレートを掛けると調整を理解できません。連結CFでも、外国通貨現金の換算差は営業・投資・財務CFとは別に示されることがあります。円現金が増えたように見えても、現地の現金数量が増えていない場合があります。')),
s('現地成長と円換算効果',table('架空の海外売上比較',['項目','前年','当年'],[['現地売上','100万ドル','110万ドル'],['平均為替','140円／ドル','150円／ドル'],['円表示売上','1億4,000万円','1億6,500万円'],['円売上増','—','17.86％程度'],['現地売上増','—','10％']])+p('円表示の売上増2,500万円のうち、前年レート一定での増収は1,400万円、当年売上に対するレート差効果は1,100万円という分け方ができます。為替一定の指標にも計算方法の違いがあるため定義を確認します。海外子会社を売却した際の換算差の振替は持分処分条件に依存し、すべてのOCIを無条件にそのまま当期利益とするわけではありません。'))],questions:[q('決算換算',p('ドル売掛金1万ドル、販売時140円、決算時150円。未回収、ヘッジなし。差損益＝ドル額×レート差。'),'期末差損益は？','為替益10万円です。'),q('回収',p('期首評価150万円の1万ドル債権を148円／ドルで回収。入金148万円、差額は当期為替損益。'),'当期差損益は？','為替損2万円です。'),q('一定為替',p('前年100万ドル、当年110万ドル。前年レート140円一定で比較。増収＝差10万ドル×140円。'),'現地成長分の円増収は？','1,400万円です。')],sources:[asbj,ifrs('ias-21-the-effects-of-changes-in-foreign-exchange-rates','IAS 21')]},
{number:17,lead:'純利益の外にも純資産を動かす項目がある。包括利益とOCI、振替の意味を学ぶ。',goal:'包括利益から純資産へつなぎ、OCIがすべて翌期利益になるわけでないことを説明できる。',sections:[
s('純利益だけが純資産を動かすわけではない',p('包括利益は、所有者との資本取引等を除く純資産変動を捉える考え方です。純利益とその他の包括利益（OCI）を合わせて見ます。OCIに入るかどうかは、各会計基準の具体的な項目によって決まり、経営者が都合により利益を外へ移せる仕組みではありません。')+flow('架空の一年の利益と持分（万円）',[['当期純利益100','通常のPLの終点'],['OCI＋20','所定の評価・換算等'],['包括利益120','100＋20'],['配当30・増資50','所有者取引で別に純資産を動かす']])+p('評価差額や為替換算差、退職給付の再測定などの表示を確認します。税効果や非支配持分の帰属もあるため、純利益とOCIを同じ範囲・税引後にそろえます。包括利益が大きいから、その全額を配当できる現金があるという意味ではありません。')),
s('純資産の期首から期末',table('架空の純資産増減（万円、他変化なし）',['項目','金額'],[['期首純資産','500'],['純利益','＋100'],['OCI','＋20'],['配当','−30'],['増資','＋50'],['期末純資産','640']])+p('配当は当期純利益を直接減らす費用ではなく、利益剰余金等を減らす所有者取引です。増資も売上ではありません。期末純資産640と期首500の差140をそのまま当期利益と呼ぶと、OCIと増資・配当が混ざります。株主資本等変動計算書や包括利益計算書を合わせて読む必要があります。')),
s('振替されるOCIとされないOCI',table('IFRSの代表例：詳細条件は各基準を確認',['OCI項目','後にPLへ振替の基本'],[['負債性金融資産のFVOCI','除却等で振替がある'],['一定の持分金融商品OCI選択','PLへリサイクルしない'],['確定給付の再測定','PLへリサイクルしない'],['在外事業の換算差','所定の処分条件で振替がある'],['CFヘッジ','対象・条件により振替や資産調整']])+p('日本基準のその他有価証券評価差額とIFRSの持分金融商品のOCI選択は、売却時の扱いが違います。非リサイクル項目でも純資産の中で振り替える場合はありますが、PL利益へ移すこととは別です。基準の違いを一つの表へ無理にまとめず、問題の前提に従います。')),
s('二重計上を防ぐ再分類調整',table('架空のリサイクル例（万円、税なし）',['段階','PL','OCI'],[['前年の時価益','0','＋20'],['当年売却で利益計上','＋20','−20の再分類調整'],['当年の当該項目包括利益','20＋（−20）＝0','二年合計は20']])+p('前年にOCIで認識した20を売却時にPLへ移す例では、当年OCI側に−20を置き、同じ利益を二年で二重に包括利益へ数えないようにします。新たな時価変動があれば別に加わります。この表はリサイクルする項目の説明であり、非リサイクル株式の処理に流用しません。'))],questions:[q('包括利益',p('純利益100、税引後OCI20（万円）。同じ帰属範囲。包括利益＝純利益＋OCI。'),'包括利益は？','120万円です。'),q('純資産',p('期首500、純利益100、OCI20、配当30、増資50（万円）。他変化なし。期末＝500＋100＋20−30＋50。'),'期末は？','640万円です。'),q('振替',p('前期OCI20、今期PLへ20振替、今期新評価差なし。再分類OCI−20。今期包括利益への当該影響＝PL＋OCI。'),'今期の影響は？','0万円です。既認識分の表示場所を変え、二重計上を避けます。')],sources:[asbj,ifrs('ias-1-presentation-of-financial-statements','IAS 1'),ifrs('ifrs-9-financial-instruments','IFRS 9'),ifrs('ias-19-employee-benefits','IAS 19')]},
{number:18,lead:'一株当たり利益は利益だけでなく株数でも動く。潜在株式と株式報酬を含めて読む。',goal:'期中平均株数によるEPSと簡略希薄化EPSを計算し、反希薄化を区別できる。',sections:[
s('EPSの分子と分母をそろえる',p('基本的EPSは、普通株主に帰属する利益を、期中平均普通株式数で割ります。親会社株主帰属利益を使うのが基本で、非支配持分を含む全体利益をそのまま使わないようにします。自己株式は発行済み株式に含まれていても、EPSの分母から除く点を確認します。期末株数だけで計算すると増資や買戻しの時期を無視します。')+table('架空のEPS計算',['項目','数値'],[['普通株主帰属利益','1億2,000万円'],['期首普通株式数・自己株控除後','100万株'],['期中株数変化','なし'],['期中平均株数','100万株'],['基本EPS','120円']])+p('優先配当や特殊な株式等がある場合は、普通株主へ帰属する分子の調整が必要です。株式分割では比較EPSを調整するので、分割後にEPSが下がっただけで企業の利益が悪化したとは言えません。利益額、平均株数、EPSを同じ表へ並べます。')),
s('増資の時期を平均へ反映',table('架空の期中平均株数（年度12か月）',['期間','株数','重み'],[['最初の6か月','100万株','6／12'],['後の6か月','120万株','6／12'],['平均','110万株','100×半分＋120×半分'],['利益1億2,100万円のEPS','110円','利益÷110万株']])+p('期末120万株だけで割ると100.83円程度になり、この条件の基本EPS110と一致しません。実際は発行日単位などで加重平均し、株式分割や無償割当等に特別な調整が必要なことがあります。ここではちょうど半年ずつという簡略設定です。自己株買いも時期を反映させます。')),
s('潜在株式と希薄化EPS',flow('架空の希薄化計算',[['基本利益1.2億円・100万株','基本EPS120円'],['転換を仮定','税引後利息600万円を分子へ戻す'],['追加株式10万株','分母110万株'],['希薄化EPS','1.26億÷110万＝約114.55円']])+p('転換社債を株式へ転換したと仮定する場合、利息がなくなる効果も分子へ調整します。分母だけ増やしてはいけません。オプションには自己株式方式等の別の計算があり、すべて想定発行株数を単純加算するわけではありません。潜在株式を入れてEPSが上がる反希薄化のものは、通常そのまま希薄化EPSへ入れません。')),
s('株式報酬は現金ゼロでもコスト',table('株式報酬を見る二つの角度',['角度','確認点'],[['会計費用','権利確定条件、付与時評価、費用配分等'],['株主の希薄化','潜在株式、交付株数、自己株処分等'],['CF','非現金費用として営業CF調整に入る場合'],['経営者指標','調整EBITDAから除く場合の定義']])+p('費用が非現金だから株主に負担がないとはいえません。将来の株数増加や既存株式の交付で株主の持分が薄まる場合があります。一方、すべての付与が直ちに同数の希薄化になるわけではなく、権利確定・失効・自己株の扱い等を確認します。利益増と買戻しによる分母減がEPSへそれぞれどれだけ寄与したかを分けて分析します。'))],questions:[q('平均株数',p('前半6か月100万株、後半6か月120万株、12か月年度、自己株等なし。平均＝100×6／12＋120×6／12。'),'平均株数は？','110万株です。'),q('基本EPS',p('普通株主帰属利益1億2,100万円、期中平均110万株。EPS＝利益÷株数。'),'EPSは？','110円です。'),q('希薄化EPS',p('利益1.2億円、基本100万株。転換で税引後利息600万円を加算、株10万を加算。式＝1.26億÷110万。反希薄化なし。'),'希薄化EPSは？','約114.55円です。')],sources:[asbj,ifrs('ias-33-earnings-per-share','IAS 33'),ifrs('ifrs-2-share-based-payment','IFRS 2')]}
);
accountingLectures.push(
{number:19,lead:'利益率・資産回転・財務レバレッジへ分解して、ROEが高い理由を探る。',goal:'分子と平均残高の対応をそろえ、ROE・ROA・ROICを使い分けられる。',sections:[
s('誰の利益を何の資本で割るか',p('ROEは株主の資本に対する利益、ROAは総資産に対する利益、ROICは事業の投下資本に対する税引後営業利益を基本に考えます。ただしROAには純利益、営業利益、経常利益など複数の分子があります。定義を明記せず同じ名前で比べないようにします。期間の利益には、その期間に対応する平均残高を使うのが基本です。')+table('本講義の架空の定義',['指標','分子','分母'],[['ROE','普通株主帰属純利益','平均自己資本'],['純利益ROA','純利益','平均総資産'],['ROIC','簡略NOPAT','平均営業投下資本']])+p('純資産には非支配持分等が含まれ得るため、親株主利益と自己資本の範囲を対応させます。ROICの投下資本も、事業資産−営業負債か、負債＋資本−非事業資産かを調整してそろえます。余剰現金、のれん、リースの範囲によって数字は変わります。')),
s('デュポン分解を計算',table('架空の年間数値（万円、平均残高）',['項目','数値'],[['売上','1,000'],['純利益','100'],['平均総資産','500'],['平均自己資本','250'],['純利益率','10％'],['総資産回転率','2回'],['財務レバレッジ','2倍'],['ROE','10％×2×2＝40％']])+p('純利益÷売上×売上÷資産×資産÷自己資本と並べると、途中の売上と資産が約分され、純利益÷自己資本へ戻ります。高ROEの理由は高利益率だけでなく、少ない資産や多い借入かもしれません。レバレッジだけで上げたROEは、損失や利息増の際に株主の負担も増幅します。')),
s('ROICと資本コスト',flow('架空の事業価値の判定（万円）',[['営業利益150・税率30％','NOPAT105'],['平均投下資本700','ROIC15％'],['資本コスト8％','要求収益56'],['経済利益','105−56＝49']])+p('ROICが資本コストを超える条件での成長は、価値創造につながる可能性があります。下回ったまま規模を増やせば、利益額が増えても経済利益が悪化し得ます。ただし過去の会計ROICと将来の限界投資ROICは別です。研究開発の費用化や買収のれんなどが比較をゆがめる場合、調整の根拠を示します。')),
s('比率だけで結論にしない',table('高低の理由を探る',['変化','確認するもの'],[['ROE上昇','利益増か買戻し・借入増か'],['ROA低下','成長前の新工場か不稼働資産か'],['ROIC上昇','採算改善か投下資本減か'],['のれん減損後のROIC上昇','分母減による見かけの改善'],['期末分母の急変','平均残高・取得時期の整合']])+p('分母が小さい会社や自己資本が負の会社では、通常の比率が意味を失うことがあります。赤字会社のROEと黒字会社のROEの順位を単純につけないようにします。利益率と回転率を業種・自社過去で比べ、基準や範囲を一致させたうえで、どこが持続的に改善したのかを説明します。'))],questions:[q('ROE分解',p('純利益100、売上1,000、平均資産500、平均自己資本250（万円）。ROE＝利益率×資産回転×レバレッジ。'),'ROEは？','10％×2×2＝40％です。'),q('ROIC',p('営業利益150、税率30％、平均投下資本700（万円）。NOPAT＝営業利益×税引後率、ROIC＝NOPAT÷投下資本。'),'ROICは？','105÷700＝15％です。'),q('経済利益',p('NOPAT105、投下資本700、資本コスト8％（万円）。経済利益＝NOPAT−投下資本×コスト。'),'経済利益は？','49万円です。')],sources:[asbj]},
{number:20,lead:'短期の支払能力と長期の財務負担を、複数の比率で点検する。',goal:'流動比率・当座比率・D/E・ICRを計算し、負債の期限とCFへつなげられる。',sections:[
s('安全性は一つの比率では決まらない',p('流動比率は流動資産÷流動負債、当座比率は換金性の高い当座資産÷流動負債です。当座資産の定義には差があるため、本講義は現金＋売掛金とします。流動資産が多くても、滞留在庫や回収不能債権では支払に使えません。額、質、入出金の時期を合わせて評価します。')+table('架空の流動資産・負債（万円）',['項目','金額'],[['現金','100'],['売掛金','150'],['在庫','250'],['流動資産合計','500'],['流動負債','250'],['流動比率','200％'],['本例の当座比率','（100＋150）÷250＝100％']])+p('流動比率200％でも、流動負債の支払が明日で売掛金回収が半年後なら資金不足になり得ます。逆に現金回収が先の小売などは、低い流動比率でも資金サイクルが安定することがあります。業種や契約を無視した万能合格基準にはしません。')),
s('D/Eは負債の範囲を決める',flow('架空の財務負担（万円）',[['有利子負債400','借入・社債等の定義を確認'],['自己資本200','D/E＝400÷200＝2倍'],['現金100','ネット負債300'],['ネットD/E','300÷200＝1.5倍']])+p('総負債÷自己資本と有利子負債÷自己資本は別です。買掛金や契約負債も含む総負債を使いながら、有利子負債D/Eと呼ばないようにします。現金から使途制限や必要運転資金を考慮せず、全額を借入相殺可能と判断することにも注意が必要です。リース負債を含めるかも明示します。')),
s('利息を何倍稼げるか',table('架空のICRとストレス（万円）',['条件','営業利益','支払利息','ICR'],[['基準','120','30','4倍'],['利益半減','60','30','2倍'],['利益半減＋利息増','60','40','1.5倍']])+p('本講義のICRは営業利益÷支払利息です。EBITDAなどを分子にする指標とは区別します。ICRは元本返済額を直接カバーする比率ではなく、減価償却や設備投資、税金、運転資本の影響も十分には表しません。金利が上がる局面では変動金利比率、借換時期、ヘッジを注記で確かめます。')),
s('満期表とCFで点検する',table('安全性の追加チェック',['対象','問い'],[['借入満期','一時期に返済が集中していないか'],['営業CF','利息だけでなく投資・元本返済へ回るか'],['手元流動性','現金と未使用枠は使えるか'],['財務制限条項','比率悪化で期限前返済にならないか'],['保証・担保','連結外リスクや資産制約がないか']])+p('利息を払えることと、来月満期の元本を払えることは別です。借換が継続できる前提にも市場や銀行関係のリスクがあります。比率の改善が増資による資本増なのか、利益蓄積なのか、負債返済なのかを区別し、資金繰り表と返済期限の組合せで評価します。'))],questions:[q('流動・当座',p('現金100、売掛金150、在庫250、流動負債250（万円）。流動比率＝三資産合計÷負債、当座＝現金と売掛金÷負債。'),'二つの比率は？','流動200％、当座100％です。'),q('D/E',p('有利子負債400、現金100、自己資本200（万円）。D/E＝負債÷資本、ネットD/E＝（負債−現金）÷資本。'),'比率は？','2倍、1.5倍です。'),q('ICR',p('営業利益60、支払利息40（万円）。ICR＝営業利益÷支払利息。'),'ICRは？','1.5倍。元本返済を含む指標ではありません。')],sources:[asbj]},
{number:21,lead:'商品を仕入れてから代金を回収するまで、何日分の資金を持つ必要があるかを計算する。',goal:'売上債権・在庫・買掛金の日数をそろえてCCCと資金改善額を計算できる。',sections:[
s('CCCは営業サイクルの資金日数',p('CCCはCash Conversion Cycleで、売上債権日数＋在庫日数−仕入債務日数とするのが基本です。売掛金は売上高、在庫や買掛金は売上原価等に対応させます。本講義は一年365日・平均残高を使用し、買掛金は売上原価を分母とする簡略定義です。仕入高を使う場合と混ぜないようにします。')+flow('営業資金の時間',[['在庫日数DIO','仕入から販売まで'],['売上債権日数DSO','販売から回収まで'],['仕入債務日数DPO','支払を後へ延ばす期間'],['CCC','DIO＋DSO−DPO']])+p('前受や現金販売が多い会社では、CCCが短くなり、場合によってはマイナスになります。期末残高だけだと季節性や決算前調整を拾いやすいため、平均や四半期の残高を検討します。業種の契約習慣を考えずに短いほど絶対によいと判断しません。')),
s('平均残高から日数へ',table('架空の年間数値（万円、平均残高）',['項目','数値','日数'],[['年間売上','3,650','一日売上10'],['年間売上原価','2,190','一日原価6'],['平均売掛金','300','DSO30日'],['平均在庫','240','DIO40日'],['平均買掛金','180','DPO30日'],['CCC','30＋40−30','40日']])+p('売掛金300÷売上3,650×365＝30日です。在庫240÷原価2,190×365＝40日です。買掛金もこの定義なら30日です。在庫を売上で割ると24日となり、粗利があるため原価ベース40日と一致しません。分母の対応をそろえるのが計算の要点です。')),
s('日数改善を必要資金へ換算',table('架空の改善策と放出資金（万円）',['策','日数変化','資金効果'],[['回収短縮','DSO−5日','5×一日売上10＝50'],['在庫短縮','DIO−10日','10×一日原価6＝60'],['支払猶予増','DPO＋5日','5×一日原価6＝30'],['合計','CCC40→20日','140の必要資金減']])+p('CCCが20日短くなっても、20×一日売上10＝200とは計算しません。売掛金と在庫・買掛金で分母が違うため、それぞれ資金効果へ戻して合計140です。この例は売上・原価・取引条件がほかに変わらず、残高がその日数へ落ち着く場合です。会社の実績として断定する数字ではありません。')),
s('回転率と日数を使い分ける',table('同じ情報を二つの表現で見る',['項目','回転率','日数'],[['売上債権','年間売上÷平均債権','365÷回転率'],['在庫','年間原価÷平均在庫','365÷回転率'],['総資産','年間売上÷平均総資産','通常は回転率で比較'],['固定資産','年間売上÷平均固定資産','資産範囲と稼働段階を確認']])+p('回転率が上がれば日数は下がりますが、過度な在庫削減で欠品が起きる場合は営業が悪化します。支払日数の伸長も交渉力か資金難かを見分けます。買収や為替、期末セール等が残高へ影響するときは、事業の持続的改善と切り分け、翌期の回収・仕入状況も確かめます。'))],questions:[q('DSO',p('年間売上3,650、平均売掛金300（万円）、365日。DSO＝債権÷売上×365。'),'DSOは？','30日です。'),q('CCC',p('DSO30、DIO40、DPO30（日）。CCC＝DSO＋DIO−DPO。'),'CCCは？','40日です。'),q('在庫改善',p('年間原価2,190万円、365日、在庫日数10日削減。他条件同じ。放出資金＝年間原価÷365×削減日数。'),'資金効果は？','60万円です。')],sources:[asbj]},
{number:22,lead:'純利益と営業CFの差から、成長に必要な資金、見積り、一時利益の影響を探る。',goal:'アクルーアルやCF転換率を条件付きで計算し、低CFを不正と断定しない分析ができる。',sections:[
s('利益の質は現金だけではない',p('会計利益は発生主義で測定され、現金の受払と時期が違います。利益の質の分析は、回収される可能性、反復性、見積りの妥当性、事業の持続性などを点検するものです。営業CFが利益を下回ることだけで不正と決めつけません。成長に伴う運転資本増や季節性でも差が出ます。')+table('架空の利益とCF（万円）',['項目','金額'],[['純利益','100'],['償却','＋30'],['売掛金増','−80'],['在庫増','−40'],['買掛金増','＋20'],['営業CF','30']])+p('この例は税・利息支払済みで他調整なしです。利益100に対してCF30ですが、差は運転資本などで説明できます。次に回収される売掛金なのか、売れ残る在庫なのか、事業の成長に不可欠な残高なのかを確認します。差を計算してから、その原因と持続性を調べます。')),
s('簡略アクルーアルと転換率',flow('架空の分析指標',[['利益100−営業CF30','簡略アクルーアル70'],['平均総資産500','比率70÷500＝14％'],['営業CF÷純利益','CF転換率30％'],['条件','定義・期間・利益範囲をそろえる']])+p('アクルーアルにも定義が複数あります。本例は純利益−営業CFとし、細かい財務調整を省略します。純利益がゼロや赤字だとCF転換率の比較が難しくなります。一年だけでなく複数年合計を見ると、売上回収時期の差をならせますが、累積債権の劣化や長期の未回収を隠さないようにします。')),
s('反復性と一時項目を分ける',table('架空の税引前利益の分解（万円）',['項目','金額','見る論点'],[['通常事業利益','120','継続性'],['固定資産売却益','50','同じ資産を毎年売れるか'],['買収費用','−20','本当に一時か反復しているか'],['合計','150','単純合計'],['計算上の通常利益','120','調整根拠を明記']])+p('一時費用を除けば必ず正しい利益になるわけではありません。毎年買収する会社の買収費用や、毎年発生する構造改革費用は反復コストかもしれません。売却益を引く際も、それに関連する税金やCF区分をそろえます。経営者の調整利益と自分の正常化を分け、足し戻しの一覧を残します。')),
s('判断が入りやすい注記を読む',table('利益の質の確認先',['領域','確かめるもの'],[['売上認識','履行・返品・変動対価・契約資産'],['債権','回収期間、貸倒見積り、集中先'],['在庫','日数、評価損、陳腐化'],['固定資産','耐用年数、減損、資本化'],['税金','DTA回収、税率、過年度調整']])+p('見積り変更がすべて悪いとはいえません。事業環境の変化を反映した合理的な変更もあります。変更理由、利益影響、前期との比較、翌期に逆転しないかを確認します。CFが良い場合も、仕入支払いの延期や債権売却などの一時要因があり得るため、現金の増加をそのまま高品質利益とは呼びません。'))],questions:[q('営業CF',p('純利益100、償却30、売掛金増80、在庫増40、買掛金増20（万円）。他調整なし。CF＝100＋30−80−40＋20。'),'営業CFは？','30万円です。'),q('アクルーアル',p('純利益100、営業CF30、平均資産500（万円）。簡略比率＝（利益−CF）÷資産。'),'比率は？','70÷500＝14％です。'),q('断定の可否',p('成長による売掛金増でも利益とCFは乖離する。回収・契約条件・複数年の動きは未確認。'),'CFが少ないだけで不正と断定できる？','できません。原因と回収可能性を確認します。')],sources:[asbj,ifrs('ias-7-statement-of-cash-flows','IAS 7')]},
{number:23,lead:'小売・製造・サービス・金融で三表の形が違う。比率のランキング前に事業モデルを読む。',goal:'在庫・設備・前受・金融負債の意味を業種ごとに説明し、比較対象を選べる。',sections:[
s('同じ比率を全業種へ当てはめない',p('製造業は在庫と設備、小売は店舗・在庫・回収サイクル、定額サービスは前受や開発費などに特徴が出ます。銀行の預金負債と製造業の借入金は、事業モデルの中で意味が違います。一般事業会社のD/EやROICを、そのまま金融機関の安全性の結論へ使うことはできません。')+table('業態と三表の見どころ',['業態','BS','PL・CF'],[['製造','設備・在庫','稼働率・原価・設備投資'],['小売','在庫・店舗・リース','粗利・回転・出店支出'],['定額サービス','契約負債・開発資産','売上認識・解約・開発投資'],['不動産','棚卸不動産・借入','販売と賃貸・利息・回収'],['金融','貸出・有価証券・預金','利鞘・信用損失・規制資本']])+p('ここでの特徴は傾向であって、すべての企業が同じ構造という意味ではありません。複合企業ならセグメントごとに事業モデルを分けます。販売と賃貸の不動産は、同じ会社でも売上の反復性と資産の分類が異なるため、部門情報へ戻る必要があります。')),
s('利益率と回転率の組合せ',table('架空の二つのモデル（税前簡略ROA）',['項目','高回転小売','高利益率サービス'],[['売上','2,000','1,000'],['営業利益','100','150'],['平均総資産','500','750'],['営業利益率','5％','15％'],['資産回転率','4回','1.333…回'],['営業利益ROA','20％','20％']])+p('サービスの利益率が三倍でも、資産回転が低いためこの条件のROAは同じ20％です。高利益率だけを評価しては資本の使い方を無視します。無形資産の費用化でBS資産が少なく見える場合や、店舗を所有するか借りるかでも比率が変わるため、同業比較でも資産範囲を確認します。')),
s('前受モデルの営業CF',flow('架空の年間契約120万円',[['先に一年分回収','現金＋120、契約負債＋120'],['3か月提供','均等なら売上30、負債残90'],['期末営業CF','未提供分回収の効果が入る'],['翌期','提供費用と解約返金の条件を確認']])+p('前受で営業CFが売上を上回る場合があっても、将来のサービス提供義務は残ります。契約負債を増やし続けられる成長期と、契約が減る局面では資金効果も変わります。売上、請求額、回収額、契約負債、解約率の定義を区別して見ます。顧客が支払ったお金をすべて当期粗利と考えないことが要点です。')),
s('同業比較に必要な条件',table('比較対象の選び方',['条件','理由'],[['事業構成','小売と卸売、販売と賃貸は違う'],['地域と通貨','需要・為替・規制が違う'],['所有かリースか','資産・償却・賃料が変わる'],['成長段階','投資前後で回転とCFが変わる'],['会計基準','のれん・開発・リース等をそろえる']])+p('銀行は自己資本規制・流動性規制・資産の信用リスクなどの専用指標を確認します。保険も負債の測定や契約の構造が一般会社とは違います。業種平均の順位表は入口であり、個社の優劣の証明ではありません。まずどの活動で利益と現金を作る会社かを一文で書き、そのモデルに適した指標を選びます。'))],questions:[q('小売のROA',p('売上2,000、営業利益100、平均資産500（万円）。営業利益ROA＝営業利益÷資産。'),'ROAは？','20％です。'),q('サービスのROA',p('売上1,000、営業利益150、平均資産750（万円）。利益率15％、回転率1,000÷750。ROA＝利益率×回転。'),'ROAは？','20％です。'),q('前受売上',p('一年契約120万円前受、均等提供3か月。売上＝120×3÷12、残額契約負債。'),'売上と契約負債は？','売上30、負債90万円です。')],sources:[asbj,ifrs('ifrs-15-revenue-from-contracts-with-customers','IFRS 15')]},
{number:24,lead:'事業ごとに利益率と資本効率を読み、部門価値を積み上げるSOTPの入口まで進む。',goal:'セグメント利益の調整を確認し、部門価値と株主価値の範囲をそろえられる。',sections:[
s('部門利益の定義を読む',p('セグメント情報は、経営者が事業をどう区分して管理しているかを理解する資料です。報告セグメントの利益が連結PLの営業利益と同じ定義とは限りません。内部売上、共通費、償却、のれん等の扱いと、全社損益への調整表を確認します。高利益率の部門でも、使う資産が大きい場合は高ROICとは限りません。')+table('架空の二部門（万円）',['項目','A事業','B事業'],[['外部売上','600','400'],['部門利益','120','20'],['利益率','20％','5％'],['部門投下資本','800','100'],['税率30％のNOPAT','84','14'],['部門ROIC','10.5％','14％']])+p('Aの利益率が高くても、ここではBの資本効率が高い結果です。部門資産の配分や共通資産の扱いでROICが変わるので、同じ定義と配賦方法を使います。セグメント変更で前期の比較数値が組み替えられた場合は、旧区分と新区分をそのままつなげないようにします。')),
s('部門利益から全社へ照合',table('架空の利益調整（万円）',['項目','金額'],[['A部門利益','120'],['B部門利益','20'],['全社費用','−30'],['内部利益等調整','−10'],['連結営業利益','100']])+p('部門合計140をそのまま会社営業利益と呼ぶと、共通費30と調整10を無視します。収益性の改善が共通費の配賦変更による場合もあるため、部門の実力改善と切り分けます。部門売上も外部売上と内部売上を分け、合計が会社の外部売上へ戻るかを確かめます。')),
s('SOTPで事業価値を足し合わせる',flow('架空のSum of the Parts（万円）',[['A事業EBITDA100×8倍','事業価値800'],['B事業EBITDA50×6倍','事業価値300'],['合計事業価値1,100','非事業資産100を加える'],['有利子負債400を引く','株主価値800']])+p('倍率はすべて架空の仮定で、市場の実際の評価ではありません。この例では全社費用、非支配持分、税、リース等の価値調整を追加せず、各事業EBITDAは価値算定用の調整後数字とします。EV倍率を使う部門の値を足すと事業価値なので、株主価値へ戻すために非事業資産と負債等を調整します。')),
s('二重計上を防ぐ',table('SOTPの点検',['誤り','直す考え方'],[['事業価値へ使った現金を再加算','事業内・非事業を分ける'],['部門利益にない全社費用を無視','全社費用の価値を調整'],['EV倍率と株価利益倍率を混在','資金の受け手をそろえる'],['他社倍率を無条件に転用','成長・リスク・基準差を確認'],['持分100％でない部門を全額株主帰属','非支配持分等を調整']])+p('SOTPの細かい数字は精密に見えても、部門ごとの倍率や将来利益の仮定で価値が大きく変わります。範囲を示し、感度を並べ、単一の確定株価と説明しないようにします。本回のSOTPは実務・応用の入口で、会計上の部門分析と市場価値の推計を分けて学びます。'))],questions:[q('利益調整',p('部門利益120と20、全社費用30、内部調整10（万円）。連結＝合計−費用−調整。'),'営業利益は？','100万円です。'),q('部門ROIC',p('部門利益20、税率30％、投下資本100（万円）。NOPAT＝利益×70％、ROIC＝NOPAT÷資本。'),'ROICは？','14％です。'),q('SOTP',p('A価値800、B価値300、非事業資産100、有利子負債400（万円）。他調整なし。株主価値＝A＋B＋資産−負債。'),'株主価値は？','800万円です。')],sources:[asbj,ifrs('ifrs-8-operating-segments','IFRS 8')]},
{number:25,lead:'実際の決算短信で対象期間・利益率・CFを確認し、有報で深掘りする問いを作る。',goal:'実績と予想、年度と四半期を分けた10分の企業分析メモを作れる。',sections:[
s('最初の一分で範囲を固定する',p('最初に企業名・対象期間・会計基準・連結範囲・単位を確認します。本回の企業実例は任天堂の2026年3月期決算短信（日本基準・連結）、2026年5月8日公表です。2026年9月17日時点では第1四半期資料もあるため、通期の三表と最新四半期を混ぜずに使います。')+flow('10分の企業分析',[['1分','期間・基準・範囲・事業を確認'],['3分','PLの利益率と増減を見る'],['3分','BSとCFの資金の動きを見る'],['3分','注記と最新資料へつなぐ問いを書く']])+p('短信からすべてを断定するのではなく、有報の重要な会計方針、監査、リスク、部門情報へつなぐ入口にします。以下の実績抜粋は一次資料の数字です。一方、練習問題の会社・金額は実例とは別の架空データで、必要な条件を各問にそろえています。')),
s('実績の利益率を確かめる',table('任天堂：通期実績の抜粋（百万円・連結）',['項目','2025年3月期','2026年3月期'],[['売上高','1,164,922','2,313,051'],['営業利益','282,553','360,117'],['営業利益率（短信表示）','24.3％','15.6％']])+p('増収増益でも営業利益率は低下しています。この三行だけでは原因を特定できないため、商品構成と原価・販管費の説明へ戻ります。数字の変化と原因の推測は別です。')+p('一般に、売上増加が数量、単価、商品構成、為替、買収のどれによるかを確認します。利益の絶対額と売上に対する率を同時に示し、利益率低下をすぐに事業失敗とは決めません。製品発売や投資の時期で年度間の構成が大きく変わる会社では、単年度の率だけで将来を決めないことが大切です。')),
s('CFと現金を別に読む',table('任天堂：2026年3月期CFの抜粋（百万円）',['項目','金額'],[['営業CF','289,789'],['投資CF','−210,054'],['財務CF','−249,714'],['期末現金及び現金同等物','1,316,680']])+p('営業CFはプラスでも、投資・財務の支出があります。投資CF全体を設備投資と決めつけず、内訳と現金の換算影響・範囲を確認します。')+p('分析メモでは、現金が減ったから営業が赤字という結論を避けます。配当、自己株式取得、借入返済、金融資産への運用などでも現金は動きます。期首現金から三つのCFと換算影響を足し、期末現金へつなぐのが基本です。BSの現金預金とCFの現金同等物の範囲が違う場合は注記で調整します。')),
s('問いを残して有報・最新資料へ',table('次に確認する分析メモ',['問い','見る場所'],[['利益率変化の理由','製品・原価・販管費の説明'],['資金の増減','CF明細、金融資産、株主還元'],['見積りのリスク','会計方針、在庫、引当、減損'],['最新の状況','2027年3月期第1四半期資料'],['将来予想','予想前提と不確実性・実績とは別欄']])+p('最新四半期の数字を通期CFの金額と比べ、同じ長さの期間のように説明しません。四半期CFを作成していない資料なら、ない数字を推測して実績として載せないことも重要です。資料の公表日と対象期間、会社予想と自分の予想を別々に書き、未確認の項目を明示します。最後に、利益・資金・リスク・未確認事項の四点を一文ずつまとめます。'))],questions:[q('架空企業の利益率',table('練習用の架空企業（万円）',['項目','前年','当年'],[['売上','1,000','1,500'],['営業利益','200','225']])+p('利益率＝営業利益÷売上。'),'増益なら利益率も上昇？','いいえ。前年20％、当年15％。金額は増え、率は下がっています。'),q('架空企業のCF',p('期首現金100、営業CF50、投資CF−40、財務CF−30、為替影響0（万円）。期末＝全て合計。'),'期末現金は？','80万円。営業CFはプラスでも現金は減ります。'),q('資料の時点',p('通期資料は12か月、四半期資料は3か月。最新四半期にCF計算書の記載なし。'),'四半期CFを通期CFの4分の1として実績にできる？','できません。期間と開示の範囲を分け、未開示は未開示と示します。')],sources:[['任天堂：2026年3月期決算短信','https://www.nintendo.co.jp/ir/pdf/2026/260508.pdf'],['任天堂：2027年3月期第1四半期決算短信','https://www.nintendo.co.jp/ir/pdf/2026/260806.pdf'],['金融庁：EDINET','https://disclosure2.edinet-fsa.go.jp/']]},
{number:26,lead:'仕入と売上原価、支払と費用を分け、期末調整が利益とBSへどう表れるかを学ぶ。',goal:'在庫と原価、前払・未払・前受・未収の基本計算ができる。',sections:[
s('売れた分だけ原価へ',p('棚卸資産は販売や生産のために保有する資産です。仕入代金がすべて当期売上原価になるとは限りません。基本の関係は期首在庫＋当期仕入−期末在庫＝売上原価です。この例は単純な商品売買で、製造原価、評価損、返品、付随費用等の別調整を省略します。')+table('架空の商品会社の原価（万円）',['項目','金額'],[['期首在庫','100'],['当期仕入','500'],['販売に使える原価','600'],['期末在庫','150'],['売上原価','450']])+p('現金支払いは買掛金や前払の増減に左右され、仕入500とも原価450とも一致しない場合があります。在庫を多く残すと原価が少なく見える関係はありますが、在庫評価や実在性が妥当である必要があり、売れない商品を都合よく高額に残せるわけではありません。')),
s('評価方法が原価へ影響する',table('架空の同一商品・10個販売（円）',['条件','FIFO','加重平均'],[['期首10個・単価100、仕入10個・単価120','同じ','同じ'],['販売10個の原価','1,000','1,100'],['期末10個の原価','1,200','1,100'],['総原価2,200の照合','1,000＋1,200','1,100＋1,100']])+p('価格上昇局面ではこの例のFIFO原価が低くなりますが、会計方針を任意に切り替えて利益を調整することはできません。IFRSのIAS 2は原価と正味実現可能価額の低い方などを基本に測定し、LIFOは認めません。日本基準の原価評価方法・収益性低下の評価等は適用する規定を確認し、両基準の細部まで同一とは説明しません。')),
s('前払と未払で費用を期間へ',flow('架空の保険・給与の期末調整',[['保険12万円を一年分支払','3か月分費用3、前払9'],['今月給与20万円・来月支払','当期費用20、未払20'],['来年サービスの前受30万円','収益ではなく契約負債等'],['提供済みで未回収','権利条件により債権等']])+p('費用認識は支払ったかだけで決めません。前払は将来のサービスを受ける権利、未払はすでに受けたサービス等の支払義務です。期末に調整しないと利益とBSの両方を誤ります。前受も負債として認識する部分と当期履行済み部分を分け、翌期に同じ費用・収益を二重に計上しないようにします。')),
s('評価損と時期差を区別',table('架空の在庫評価（万円）',['項目','金額'],[['原価','150'],['適用基準・本例での正味売却見込額','120'],['必要な評価減','30'],['評価後在庫','120']])+p('この表は適用される低価評価の要件を満たした簡略例です。評価損30は現金の当期支出ではありませんが、商品を予定額で回収できなくなった情報です。在庫回転の低下、販売値引き、廃棄と合わせて判断します。費用を将来へ繰り延べられるかは資産認識の要件によるため、赤字回避のために支出を何でも資産化することはできません。'))],questions:[q('売上原価',p('期首在庫100、仕入500、期末在庫150（万円）。原価＝期首＋仕入−期末。他調整なし。'),'原価は？','450万円です。'),q('前払',p('一年保険12万円を期首支払、3か月経過、均等費用。費用＝12×3÷12、前払＝支払−費用。'),'費用と前払は？','3万円と9万円です。'),q('評価減',p('原価150、所定の売却見込額120（万円）。低い方へ評価する条件成立。評価損＝原価−見込額。'),'評価損は？','30万円です。')],sources:[asbj,ifrs('ias-2-inventories','IAS 2')]},
{number:27,lead:'利益蓄積・増資・配当・自己株買いを区別し、純資産と配当可能額の違いを学ぶ。',goal:'株主資本等変動計算書の簡略増減と、法的な分配規制の位置付けを説明できる。',sections:[
s('純資産と株主資本は同じ範囲とは限らない',p('日本基準の純資産には、株主資本のほか、評価・換算差額等、新株予約権、非支配株主持分などが含まれる場合があります。株主資本には資本金、資本剰余金、利益剰余金、控除項目の自己株式等があります。資本金は現金がそのまま保管されている箱ではなく、資本の会計区分です。')+table('日本基準の架空の純資産構成（万円）',['項目','金額'],[['資本金','100'],['資本剰余金','50'],['利益剰余金','300'],['自己株式','−20'],['株主資本','430'],['評価・換算差額等','30'],['非支配株主持分','10'],['純資産','470']])+p('自己株式は通常資産ではなく純資産の控除項目です。会社が自分の株を買ったから売買目的有価証券が増えた、と説明してはいけません。利益とROEの分母を対応させるためにも、自己資本と純資産の範囲を確認します。')),
s('増減表で所有者取引を分ける',table('架空の株主資本の一年（万円、他変化なし）',['項目','金額'],[['期首株主資本','430'],['親株主に対応する純利益','＋100'],['配当','−30'],['増資','＋50'],['自己株取得','−20'],['期末株主資本','530']])+p('純利益は営業成果等、配当・増資・自己株取得は所有者との取引です。増資50を売上に加えたり配当30を営業費用にしたりすると、PLとBSを混同します。自己株式の処分や消却の純資産内振替は別の項目で、消却だけで同額の現金が再び減ると考えないようにします。')),
s('配当可能額は現金や純利益と別',flow('配当を判断する三つの確認',[['会計利益','利益剰余金等がどう動いたか'],['法的な分配可能額','会社法・会社計算規則の調整を確認'],['現金と将来支払','実際に払えるかをCFで確認'],['経営判断','投資・安全性・株主還元方針']])+p('連結純利益や連結純資産をそのまま法的分配可能額とみなせません。日本の分配規制は個別の計算書類等を基に所定の加減算を行い、会社法上の純資産額300万円の制約なども確認します。現金が多くても分配可能額が足りない場合、逆に会計上分配できても資金繰り上危険な場合があります。ここでは法定計算の全項目を省略せず知っているかのように扱わず、概念の区別を学びます。')),
s('買戻しとEPS・ROE',table('架空の自己株買いの感度（通年効果と仮定）',['項目','前','後'],[['純利益','100万円','100万円'],['平均自己資本','500万円','400万円'],['平均株数','10万株','8万株'],['ROE','20％','25％'],['EPS','10円','12.5円']])+p('利益が増えなくても、自己資本や株数を減らせばROEとEPSは上がることがあります。この架空例は買戻しの通年効果を置いており、実際は取得時期や利息・運用収益も影響します。指標上昇を事業改善と即断せず、買戻し価格、財務負担、成長投資の機会を合わせて判断します。自己株取得の資金は通常財務CFで確認します。'))],questions:[q('株主資本',p('資本金100、資本剰余金50、利益剰余金300、自己株式20（万円）。株主資本＝前三項合計−自己株。'),'株主資本は？','430万円です。'),q('増減',p('期首430、純利益100、配当30、増資50、自己株取得20（万円）。他変化なし。期末＝430＋100−30＋50−20。'),'期末は？','530万円です。'),q('分配可能額',p('連結純利益と法定分配可能額は別。法定額は個別計算書類等と会社法の調整、支払能力は現金とCFで確認。'),'連結利益100なら必ず100配当できる？','いいえ。法的な額と資金の両方を確認します。')],sources:[asbj,['e-Gov：会社法','https://laws.e-gov.go.jp/law/417AC0000000086']]},
{number:28,lead:'固定費・変動費を分け、黒字化に必要な売上と価格変化への感度を計算する。',goal:'限界利益率・損益分岐点・安全余裕率と、付加価値・生産性の定義を説明できる。',sections:[
s('費用を売上との動きで分ける',p('変動費は販売量等に応じて動く費用、固定費は一定の範囲・期間では大きく変わらない費用です。PLの原価と販管費の分類とは別の軸です。原価にも工場の固定費があり、販管費にも販売手数料などの変動費があります。全原価を変動費、全販管費を固定費と決めません。')+table('架空の管理会計PL（万円）',['項目','金額'],[['売上','1,000'],['変動費','600'],['限界利益','400'],['固定費','300'],['営業利益','100'],['限界利益率','40％']])+p('限界利益は売上−変動費で、固定費を回収したあと利益になります。売上総利益とは分類が違うため一致するとは限りません。この例は価格・商品構成・変動費率・固定費が範囲内で一定という線形モデルです。設備能力を超えた増産では固定費が段階的に増える点にも注意します。')),
s('損益分岐点と安全余裕',flow('架空の黒字化ライン（万円）',[['固定費300','限界利益率40％で回収'],['損益分岐点売上','300÷40％＝750'],['現在売上1,000','差250が安全余裕'],['安全余裕率','（1,000−750）÷1,000＝25％']])+p('損益分岐点は会計上利益がゼロとなる売上であり、借入元本返済や設備投資をすべて払える資金分岐点ではありません。売上が25％下がるまで赤字にならないというのも、費用条件が維持される場合の感度です。値下げや人員増が起きれば線は変わります。計算の前に、どの条件を固定するかを一つずつ書きます。')),
s('数量・価格・変動原価の感度',table('架空の一商品モデル（円）',['項目','基準','値下げ後'],[['販売価格','1,000','900'],['一個変動費','600','600'],['一個限界利益','400','300'],['固定費','300,000','300,000'],['分岐点数量','750個','1,000個']])+p('一個の値下げ100は売上単価の10％でも、限界利益400から300への25％減です。利益100万円を目標にする場合、必要売上は（固定費＋目標利益）÷限界利益率です。価格だけでなく原材料高や低限界利益商品の構成増でも分岐点が上がります。複数商品では構成一定という前提が必要です。')),
s('付加価値と生産性の定義',table('架空の簡略付加価値分析（万円）',['項目','金額'],[['営業利益','100'],['人件費','200'],['減価償却','50'],['本例の付加価値','350＝三項合計'],['平均従業員数','10人'],['一人当たり付加価値','35万円／人'],['労働分配率','200÷350＝約57.14％']])+p('付加価値には控除法・加算法など複数の定義があります。本例は営業利益＋人件費＋償却の簡略加算法で、利息・賃借料等を含める定義とは区別します。一人当たり売上の上昇だけで従業員の実力向上を断定しません。外注化、設備化、商品構成、労働時間で数値が変わるため、人員と付加価値の範囲をそろえて比較します。'))],questions:[q('損益分岐点',p('固定費300万円、変動費率60％、価格等一定。限界利益率40％、分岐点売上＝固定費÷限界利益率。'),'分岐点売上は？','750万円です。'),q('安全余裕',p('現在売上1,000、分岐点750（万円）。安全余裕率＝（現在−分岐点）÷現在。'),'安全余裕率は？','25％です。'),q('分岐点数量',p('単価900円、変動費600円／個、固定費30万円。分岐点量＝固定費÷（単価−変動費）。'),'何個でゼロ利益？','1,000個です。')],sources:[asbj]}
);
const supplements={
4:['借入で運転資本を埋めた場合',p('営業運転資本が80増え、借入80を新たに調達したとします。現金残高は変わらないことがあっても、事業の必要資金と金融負債は両方増えています。借入金を営業運転資本から引いてゼロとすると、事業の資金需要を見えなくします。')+table('架空の追加資金80万円',['流れ','CF'],[['事業の必要資金増','営業側−80'],['新規借入','財務側＋80'],['現金の差引','0、ただし借入負担は増加']])],
14:['内部貸付と外部借入を分ける',p('親が銀行から100を借り、その100を子へ貸したとします。連結では親子間の貸付金と借入金100は消えますが、銀行への負債100は残ります。グループ外に返済すべき義務は内部消去できません。')+table('架空の連結消去（万円）',['項目','連結の扱い'],[['親の子向け貸付100','内部債権として消去'],['子の親向け借入100','内部債務として消去'],['親の銀行借入100','外部債務なので残る']])],
17:['OCIの帰属もそろえる',p('税引後OCI30のうち親株主25、非支配株主5とします。親株主純利益100と合わせた親株主包括利益は125です。親株主純利益100に全体OCI30を足して130とすると、帰属範囲が混ざります。')+table('架空の包括利益の帰属（万円）',['項目','親株主','非支配株主'],[['純利益','100','10'],['OCI','25','5'],['包括利益','125','15']])],
20:['利益があっても期限で困る',p('手元現金100、来月回収30、来月返済元本150とします。他支払も調達もなければ20不足します。営業利益が年間120あっても、この不足は埋まりません。月別資金計画と確実に使える融資枠を確認します。')+table('架空の来月の資金（万円）',['項目','金額'],[['手元現金','100'],['回収','＋30'],['元本返済','−150'],['不足','20']])],
22:['二年合計でも回収を確かめる',p('一年目の利益100・営業CF30、二年目の利益100・営業CF170なら、二年合計はともに200です。回収時期のずれがならされた例ですが、別の債権が増えていないか、支払を先送りしていないかは引き続き確認します。')+table('架空の二年のCF転換（万円）',['項目','一年目','二年目','合計'],[['純利益','100','100','200'],['営業CF','30','170','200'],['転換率','30％','170％','100％']])]
};
for(const [n,[title,html]] of Object.entries(supplements))accountingLectures.find(d=>d.number===Number(n)).sections.push(s(title,html));
